async function loadBilling(){
 const [plans,e,cfg,payments,profile]=await Promise.all([api('/api/plans'),api('/api/billing/entitlements'),api('/api/billing/config'),api('/api/billing/payments'),api('/api/account/profile')]);
 const sub=profile.subscription||{},current=profile.plan||{};
 $('#currentPlan').textContent=e.plan_name+' · '+(e.ends_at?(T('js.expires_prefix','vence')+' '+new Date(e.ends_at).toLocaleDateString()):T('js.active_status','activo'));
 $('#membershipSummary').innerHTML=`<article class="membership-card"><div><span class="account-badge">${T('js.your_membership','Tu membresía')}</span><h2>${esc(e.plan_name)}</h2><p>${esc(current.description||'')}</p></div><div class="membership-meta"><span>${T('js.start_prefix','Inicio')} <b>${sub.starts_at?new Date(sub.starts_at).toLocaleDateString():'—'}</b></span><span>${T('js.expiration','Caducidad')} <b>${sub.ends_at?new Date(sub.ends_at).toLocaleDateString():'—'}</b></span><span>${T('js.days_remaining','Días restantes')} <b>${profile.days_remaining??0}</b></span><span>${T('js.status_prefix','Estado')} <b>${esc(sub.status||e.subscription_status)}</b></span></div></article>`;
 const usage=[[T('js.stat_users','Usuarios'),e.users_used,e.max_users],[T('js.limit_contacts','Contactos'),e.contacts_used,e.max_contacts],[T('js.stat_products_used','Productos'),e.products_used,e.max_products],[T('js.stat_rules_used','Automatizaciones'),e.rules_used,e.max_rules],[T('js.stat_ai_replies','Respuestas IA'),e.ai_used,e.max_ai_responses]];
 $('#usageGrid').innerHTML=usage.map(x=>`<div class="stat"><b>${x[1]} / ${x[2]}</b><small>${x[0]}</small></div>`).join('');
 const extras={free:[T('js.plan_extra_free1','1 agente IA'),T('js.plan_extra_free2','1 conexión total'),T('js.plan_extra_free3','2 campañas orgánicas'),T('js.plan_extra_free4','1 landing'),T('js.plan_extra_free5','1 grupo')],personal:[T('js.plan_extra_personal1','2 agentes IA'),T('js.plan_extra_personal2','2 conexiones totales'),T('js.plan_extra_personal3','10 campañas orgánicas'),T('js.plan_extra_personal4','5 landings'),T('js.plan_extra_personal5','5 grupos')],business:[T('js.plan_extra_business1','5 agentes IA'),T('js.plan_extra_business2','5 conexiones totales'),T('js.plan_extra_business3','Campañas orgánicas, pagadas y combinadas'),T('js.plan_extra_business4','25 landings'),T('js.plan_extra_business5','30 grupos'),T('js.plan_extra_business6','Equipo de hasta 5 usuarios')],enterprise:[T('js.plan_extra_enterprise1','15 agentes IA'),T('js.plan_extra_enterprise2','15 conexiones totales'),T('js.plan_extra_enterprise3','Orquestador y auditoría'),T('js.plan_extra_enterprise4','150 landings'),T('js.plan_extra_enterprise5','200 grupos'),T('js.plan_extra_enterprise6','Equipo de hasta 15 usuarios')]};
 const rank={free:0,personal:1,business:2,enterprise:3},currentRank=rank[e.plan_code]??0;
 $('#upgradePlansTitle').textContent=currentRank>=3?T('js.plan_features_title','Características de tu plan'):T('js.upgrade_membership_title','Mejorar membresía');
 $('#plansGrid').innerHTML=plans.filter(p=>p.code===e.plan_code||(rank[p.code]??0)>currentRank).map(p=>`<article class="plan-card ${p.code==='business'?'featured':''}"><span class="account-badge">${esc(p.name)}</span><h3>${esc(p.description)}</h3><div class="plan-price">${p.price_usdt===0?T('js.free_word','Gratis'):p.price_usdt+' USDT'}<small>${p.price_usdt?'/'+p.billing_days+' '+T('js.per_days','días'):''}</small></div><ul><li>${p.max_users} ${T('js.users_count','usuario(s)')}</li><li>${p.max_channels} ${T('js.channels_count','conexión(es) aislada(s)')}</li><li>${p.max_contacts.toLocaleString()} ${T('js.contacts_count','contactos')}</li><li>${p.max_ai_responses.toLocaleString()} ${T('js.ai_replies_count','respuestas IA')}</li>${(extras[p.code]||[]).map(x=>`<li>${x}</li>`).join('')}</ul>${p.code===e.plan_code?`<button disabled>${T('js.current_plan_btn','Tu plan actual')}</button>`:`<button onclick='buyPlan(${JSON.stringify(p)},${JSON.stringify(cfg)})'>${T('js.upgrade_to','Actualizar a')} ${esc(p.name)}</button>`}</article>`).join('');
 $('#myPayments').innerHTML=payments.length?`<div class="admin-table-wrap"><table class="table"><tr><th>${T('js.th_date','Fecha')}</th><th>${T('js.th_plan','Plan')}</th><th>${T('js.th_network','Red')}</th><th>${T('js.th_amount','Monto')}</th><th>${T('js.th_transaction','Transacción')}</th><th>${T('js.th_status','Estado')}</th><th>${T('js.th_note','Nota')}</th></tr>${payments.map(x=>`<tr><td>${new Date(x.created_at).toLocaleString()}</td><td>${esc(x.plan_name)}</td><td>${esc(x.network)}</td><td>${x.amount_usdt} USDT</td><td><span class="mini">${esc(x.tx_hash)}</span></td><td class="status-${x.status}">${esc(x.status)}</td><td>${esc(x.admin_note||'')}</td></tr>`).join('')}</table></div>`:`<p>${T('js.no_payments_registered','No tienes pagos registrados.')}</p>`;
}
window.buyPlan=(p,cfg)=>{let applied=null;modal(`<h2>${T('js.buy_plan_title','Comprar plan')} ${esc(p.name)}</h2><p id="payAmountText">${T('js.send_exactly','Envía exactamente')} <b>${p.price_usdt} USDT</b> ${T('js.available_network_text','por una de las redes disponibles y después registra el hash.')}</p><div class="payment-box"><label>Código promocional (opcional)<div class="inline-actions"><input id="promoCode" placeholder="Ej: WORKTIC20"><button type="button" id="applyPromo" class="secondary">Aplicar</button></div><small id="promoResult"></small></label><label>${T('js.th_network','Red')}<select id="payNetwork"><option value="BEP20">BEP20 (BNB Smart Chain)</option><option value="TRC20">TRC20 (TRON)</option></select></label><div><small>${T('js.payment_address','Dirección de pago')}</small><div id="payWallet" class="wallet"></div></div><label>${T('js.tx_hash_label','Hash de la transacción')}<input id="payHash" placeholder="0x... o hash TRON"></label><div class="notice">${T('js.payment_network_notice','Verifica que estés enviando USDT por la red elegida. Los fondos enviados por otra red podrían perderse. El plan se activa después de la verificación del administrador.')}</div><div class="actions"><button type="button" id="submitPayment">${T('js.register_payment','Registrar pago')}</button><button value="cancel" class="secondary">${T('js.cancel','Cancelar')}</button></div></div>`);const net=$('#payNetwork'),wallet=$('#payWallet'),amount=$('#payAmountText'),result=$('#promoResult');const draw=()=>wallet.textContent=net.value==='BEP20'?(cfg.bep20_address||T('js.not_configured','No configurada')):(cfg.trc20_address||T('js.not_configured','No configurada'));net.onchange=draw;draw();$('#applyPromo').onclick=async()=>{try{const code=$('#promoCode').value.trim();const x=await api('/api/billing/promo/validate',{method:'POST',body:JSON.stringify({plan_code:p.code,code})});applied=x;amount.innerHTML=`Envía exactamente <b>${x.final_amount} USDT</b> <s>${x.original_amount} USDT</s>`;result.textContent=`Código ${x.code} aplicado: ${x.discount_percent}% de descuento.`;result.className='success'}catch(e){applied=null;amount.innerHTML=`Envía exactamente <b>${p.price_usdt} USDT</b>`;result.textContent=e.message;result.className='error'}};$('#submitPayment').onclick=async()=>{try{await api('/api/billing/checkout',{method:'POST',body:JSON.stringify({plan_code:p.code,network:net.value,tx_hash:$('#payHash').value,promo_code:applied?.code||''})});$('#modal').close();toast(T('js.payment_registered','Pago registrado para verificación'));loadBilling()}catch(e){toast(e.message)}}}
async function loadAdmin(){
 const [o,p,s]=await Promise.all([api('/api/admin/overview'),api('/api/admin/payments'),api('/api/admin/subscriptions')]);
 $('#adminStats').innerHTML=[[T('js.stat_users','Usuarios'),o.users],[T('js.admin_stat_active_users','Usuarios activos'),o.active_users],[T('js.admin_stat_pending_payments','Pagos pendientes'),o.pending_payments],[T('js.admin_stat_approved_payments','Pagos aprobados'),o.approved_payments],[T('js.admin_stat_revenue','Ventas USDT'),o.revenue_usdt],[T('js.admin_stat_active_subs','Suscripciones activas'),o.active_subscriptions]].map(x=>`<div class="stat"><b>${x[1]}</b><small>${x[0]}</small></div>`).join('');
 $('#adminPayments').innerHTML=p.length?`<div class="admin-table-wrap"><table class="table"><tr><th>${T('js.th_user','Usuario')}</th><th>${T('js.th_plan','Plan')}</th><th>${T('js.th_network_amount','Red/monto')}</th><th>${T('js.th_hash','Hash')}</th><th>${T('js.th_status','Estado')}</th><th>${T('js.th_action','Acción')}</th></tr>${p.map(x=>`<tr><td><b>${esc(x.user_name)}</b><small>${esc(x.user_email)}</small></td><td>${esc(x.plan_name)}</td><td>${esc(x.network)} · ${x.amount_usdt}</td><td><span class="mini">${esc(x.tx_hash)}</span></td><td class="status-${x.status}">${esc(x.status)}</td><td>${x.status==='pending'?`<button onclick="reviewPayment(${x.id},'approve')">${T('js.approve','Aprobar')}</button> <button class="danger" onclick="reviewPayment(${x.id},'reject')">${T('js.reject','Rechazar')}</button>`:''}</td></tr>`).join('')}</table></div>`:`<p>${T('js.no_payments','No hay pagos.')}</p>`;
 $('#adminSubscriptions').innerHTML=`<div class="admin-table-wrap"><table class="table"><tr><th>${T('js.th_user','Usuario')}</th><th>${T('js.th_company','Empresa')}</th><th>${T('js.th_plan','Plan')}</th><th>${T('js.th_status','Estado')}</th><th>${T('js.th_expires','Vence')}</th></tr>${s.map(x=>`<tr><td><b>${esc(x.user_name)}</b><small>${esc(x.user_email)}</small></td><td>${esc(x.company)}</td><td>${esc(x.plan_name)}</td><td>${esc(x.status)}</td><td>${new Date(x.ends_at).toLocaleDateString()}</td></tr>`).join('')}</table></div>`;
}
