async function loadMarketingLeads(){const xs=await api('/api/marketing/leads');$('#marketingLeads').innerHTML=xs.length?`<div class="admin-table-wrap"><table class="table"><tr><th>${T('js.th_date','Fecha')}</th><th>Lead</th><th>${T('js.source_label','Fuente')}</th><th>${T('js.interest_label','Interés')}</th><th>Score</th><th>${T('js.consent_label','Consentimiento')}</th></tr>${xs.map(x=>`<tr><td>${new Date(x.created_at).toLocaleString()}</td><td><b>${esc(x.name||T('js.no_name','Sin nombre'))}</b><small>${esc(x.phone)} · ${esc(x.email)}</small></td><td>${esc(x.source)}<small>${esc(x.utm_campaign||'')}</small></td><td>${esc(x.interest)}</td><td><span class="lead-score">${x.score}</span></td><td>${x.consent?T('js.yes_word','Sí'):T('js.no_word','No')}</td></tr>`).join('')}</table></div>`:`<p>${T('js.no_leads_yet','Aún no hay leads capturados.')}</p>`}
