$$('.group-tabs button').forEach(b=>b.onclick=()=>{$$('.group-tabs button,.group-panel').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#group-'+b.dataset.groupTab).classList.add('active');if(b.dataset.groupTab==='prospects')loadGroupProspects()});
async function loadGroups(){
 const [lim,groups,prospects]=await Promise.all([api('/api/groups/limits'),api('/api/groups'),api('/api/groups/prospects')]);groupLimits=lim;
 $('#groupPlan').textContent=`${lim.plan} · ${lim.max_managed} ${T('js.groups_word','grupos')} · ${lim.max_prospects} ${T('js.saved_word','guardados')}`;
 $('#groupStats').innerHTML=[[T('js.stat_managed','Gestionados'),groups.length],[T('js.stat_saved','Guardados'),prospects.length],[T('js.stat_discovery','Descubrimiento'),lim.discovery?T('js.active','Activo'):T('js.limited_word','Limitado')],[T('js.stat_ai_replies','Respuestas IA'),lim.ai_replies?T('js.included_word','Incluidas'):T('js.not_included_word','No incluidas')]].map(x=>`<div class="stat"><b>${x[1]}</b><small>${x[0]}</small></div>`).join('');
 renderManagedGroups(groups);renderGroupProspects(prospects);
}
function renderManagedGroups(xs){$('#managedGroupsGrid').innerHTML=xs.length?xs.map(g=>`<article class="product-card group-card"><span class="group-platform">${esc(g.platform)}</span><h3>${esc(g.name)}</h3><p>${esc(g.niche||T('js.no_niche','Sin nicho'))}</p><small>ID: ${esc(g.external_id)}</small><small>${T('js.bot_prefix','Bot')}: ${g.bot_enabled?T('js.active','Activo'):T('js.paused','Pausado')} · ${T('js.mode_prefix2','Modo')}: ${esc(g.auto_reply_mode)}</small>${g.url?`<p><a href="${esc(g.url)}" target="_blank" rel="noopener">${T('js.open_group','Abrir grupo')}</a></p>`:''}<div class="actions"><button onclick="sendGroupMessage(${g.id})">${T('js.send_message','Enviar mensaje')}</button><button class="secondary" onclick="editGroup(${g.id})">${T('js.configure','Configurar')}</button><button class="danger" onclick="deleteGroup(${g.id})">${T('js.delete','Eliminar')}</button></div></article>`).join(''):`<p>${T('js.no_managed_groups','No hay grupos gestionados todavía.')}</p>`}
$('#newManagedGroup').onclick=()=>openGroupModal();
function openGroupModal(g={}){modal(`<h2>${g.id?T('js.configure_word','Configurar'):T('js.add_word','Agregar')} ${T('js.group_word','grupo')}</h2><label>${T('js.platform_label','Plataforma')}<select id="gpPlatform"><option value="whatsapp">WhatsApp</option><option value="telegram">Telegram</option><option value="facebook">Facebook</option></select></label><label>${T('js.name_label','Nombre')}<input id="gpName" value="${esc(g.name||'')}"></label><label>${T('js.group_id_label','ID del grupo')}<input id="gpExternal" value="${esc(g.external_id||'')}" placeholder="${T('js.group_id_ph','WhatsApp: ...@g.us · Telegram: chat_id o @username')}"></label><label>${T('js.public_link_label','Enlace público o interno')}<input id="gpURL" value="${esc(g.url||'')}"></label><label>${T('js.niche_label','Nicho')}<input id="gpNiche" value="${esc(g.niche||'')}"></label><label>${T('js.welcome_message_label','Mensaje de bienvenida')}<textarea id="gpWelcome">${esc(g.welcome_message||'')}</textarea></label><label>${T('js.reply_mode_label','Modo de respuesta')}<select id="gpMode"><option value="mention">${T('js.mode_mentions_only','Solo menciones/comandos')}</option><option value="all">${T('js.mode_all_messages','Todos los mensajes permitidos')}</option><option value="manual">${T('js.mode_manual_only','Solo manual')}</option></select></label><label class="check"><input id="gpEnabled" type="checkbox" ${g.bot_enabled!==false?'checked':''}> ${T('js.enable_bot_group','Activar bot en este grupo')}</label><div class="actions"><button type="button" id="saveManagedGroup">${T('js.save','Guardar')}</button><button value="cancel" class="secondary">${T('js.cancel','Cancelar')}</button></div>`);$('#gpPlatform').value=g.platform||'whatsapp';$('#gpMode').value=g.auto_reply_mode||'mention';document.addEventListener('click',async function h(ev){if(ev.target?.id!=='saveManagedGroup')return;document.removeEventListener('click',h);const d={id:g.id||0,platform:$('#gpPlatform').value,name:$('#gpName').value,external_id:$('#gpExternal').value,url:$('#gpURL').value,niche:$('#gpNiche').value,welcome_message:$('#gpWelcome').value,auto_reply_mode:$('#gpMode').value,bot_enabled:$('#gpEnabled').checked};try{await api('/api/groups',{method:g.id?'PUT':'POST',body:JSON.stringify(d)});$('#modal').close();toast(T('js.group_saved','Grupo guardado'));loadGroups()}catch(e){toast(e.message)}})}
window.editGroup=async id=>{const xs=await api('/api/groups'),g=xs.find(x=>x.id===id);if(g)openGroupModal(g)};
