function openProspectModal(x){modal(`<h2>${T('js.save_prospect_title','Guardar grupo potencial')}</h2><label>${T('js.platform_label','Plataforma')}<select id="prPlatform"><option>facebook</option><option>telegram</option><option>whatsapp</option></select></label><label>${T('js.name_label','Nombre')}<input id="prName"></label><label>${T('js.link_label','Enlace')}<input id="prURL"></label><label>${T('js.niche_label','Nicho')}<input id="prNiche" value="${esc(x.niche||'')}"></label><label>${T('js.notes_label','Notas')}<textarea id="prNotes"></textarea></label><div class="actions"><button type="button" id="saveProspect">${T('js.save','Guardar')}</button><button value="cancel" class="secondary">${T('js.cancel','Cancelar')}</button></div>`);$('#prPlatform').value=x.platform||'facebook';document.addEventListener('click',async function h(ev){if(ev.target?.id!=='saveProspect')return;document.removeEventListener('click',h);try{await api('/api/groups/discovery',{method:'POST',body:JSON.stringify({platform:$('#prPlatform').value,name:$('#prName').value,url:$('#prURL').value,niche:$('#prNiche').value,notes:$('#prNotes').value})});$('#modal').close();toast(T('js.group_saved','Grupo guardado'));loadGroups()}catch(e){toast(e.message)}})}
