function renderGroupProspects(xs){$('#groupProspectsTable').innerHTML=xs.length?`<div class="admin-table-wrap"><table class="table"><tr><th>${T('js.platform_label','Plataforma')}</th><th>${T('js.th_group','Grupo')}</th><th>${T('js.th_niche','Nicho')}</th><th>${T('js.th_notes','Notas')}</th><th></th></tr>${xs.map(x=>`<tr><td>${esc(x.platform)}</td><td><b>${esc(x.name)}</b>${x.url?`<small><a href="${esc(x.url)}" target="_blank" rel="noopener">${T('js.open_word','Abrir')}</a></small>`:''}</td><td>${esc(x.niche)}</td><td>${esc(x.notes)}</td><td><button class="danger" onclick="deleteProspect(${x.id})">${T('js.delete','Eliminar')}</button></td></tr>`).join('')}</table></div>`:`<p>${T('js.no_saved_groups','No hay grupos guardados.')}</p>`}
