let aiAgents=[],agentRoutes=[],agentMetrics=[],agentPermissions=[];
$$('[data-agent-tab]').forEach(b=>b.onclick=()=>{$$('[data-agent-tab],.agent-panel').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#agent-tab-'+b.dataset.agentTab).classList.add('active');if(b.dataset.agentTab==='routes')loadAgentRoutes();if(b.dataset.agentTab==='metrics')loadAgentMetrics();if(b.dataset.agentTab==='permissions')loadAgentPermissions()});
async function loadAIAgents(){
 const x=await api('/api/agents');aiAgents=x.agents||[];$('#agentPlan').textContent=`${x.plan}: ${aiAgents.length}/${x.limit} ${T('js.agents_word','agentes')}`;
 $('#agentStats').innerHTML=[[T('js.stat_agents','Agentes'),aiAgents.length],[T('js.stat_active_agents','Activos'),aiAgents.filter(a=>a.status==='active').length],[T('js.stat_responses_month','Respuestas mes'),aiAgents.reduce((n,a)=>n+(a.used_responses||0),0)],[T('js.stat_main_agent','Principal'),aiAgents.find(a=>a.is_default)?.name||T('js.pending_word','Pendiente')]].map(v=>`<div class="stat"><b>${esc(v[1])}</b><small>${v[0]}</small></div>`).join('');
 $('#newAIAgent').hidden=!x.can_manage;
 $('#agentsGrid').innerHTML=aiAgents.length?aiAgents.map(a=>`<article class="product-card"><div class="section-head"><div><small>${esc(a.type)} · ${esc(a.status)}</small><h3>${esc(a.name)}</h3></div>${a.is_default?`<span class="pill">${T('js.main_pill','Principal')}</span>`:''}</div><p>${esc(a.objective||a.description||T('js.no_objective_defined','Sin objetivo definido'))}</p><p><b>${T('js.channels_prefix','Canales')}:</b> ${esc(a.channels||T('js.unassigned','Sin asignar'))}</p><p><b>${T('js.consumption_prefix','Consumo')}:</b> ${a.used_responses||0}${a.monthly_budget?` / ${a.monthly_budget}`:''} ${T('js.responses_word','respuestas')}</p><div class="actions"><button onclick="editAIAgent(${a.id})">${T('js.edit','Editar')}</button><button class="secondary" onclick="testAIAgent(${a.id})">${T('js.test_word','Probar')}</button>${!a.is_default?`<button class="danger" onclick="deleteAIAgent(${a.id})">${T('js.delete','Eliminar')}</button>`:''}</div></article>`).join(''):`<article><h3>${T('js.create_first_agent_title','Crea tu primer agente especializado')}</h3><p>${T('js.create_first_agent_desc','Define un agente principal y después agrega ventas, soporte, agenda, campañas o comunidades según tu plan.')}</p></article>`;
}
$('#newAIAgent').onclick=()=>openAIAgentEditor({type:'sales',tone:T('js.professional_close_tone','Profesional y cercano'),language:'es',status:'draft',tools:'contact,opportunity,appointment,handoff',channels:'',monthly_budget:0});
window.editAIAgent=id=>{const a=aiAgents.find(x=>x.id===id);if(a)openAIAgentEditor(a)};
function openAIAgentEditor(a={}){modal(`<h2>${a.id?T('js.edit','Editar'):T('js.new','Nuevo')} ${T('js.new_ai_agent_title','agente IA')}</h2><div class="form"><label>${T('js.name_label','Nombre')}<input id="maName" value="${esc(a.name||'')}"></label><div class="grid2"><label>${T('js.type_label','Tipo')}<select id="maType">${['general','sales','support','appointments','campaigns','community','custom'].map(x=>`<option ${a.type===x?'selected':''}>${x}</option>`).join('')}</select></label><label>${T('js.state_label','Estado')}<select id="maStatus"><option value="draft" ${a.status==='draft'?'selected':''}>${T('js.state_draft','Borrador')}</option><option value="active" ${a.status==='active'?'selected':''}>${T('js.state_active','Activo')}</option><option value="paused" ${a.status==='paused'?'selected':''}>${T('js.state_paused','Pausado')}</option></select></label></div><label>${T('js.objective_label','Objetivo')}<textarea id="maObjective">${esc(a.objective||'')}</textarea></label><div class="grid2"><label>${T('js.tone_label','Tono')}<input id="maTone" value="${esc(a.tone||T('js.professional_close_tone','Profesional y cercano'))}"></label><label>${T('js.language_label','Idioma')}<input id="maLanguage" value="${esc(a.language||'es')}"></label></div><label>${T('js.instructions_label','Instrucciones')}<textarea id="maInstructions" rows="5">${esc(a.instructions||'')}</textarea></label><label>${T('js.exclusive_knowledge_label','Conocimiento exclusivo')}<textarea id="maKnowledge" rows="5">${esc(a.knowledge||'')}</textarea></label><label>${T('js.allowed_tools_label','Herramientas permitidas')}<input id="maTools" value="${esc(a.tools||'')}"></label><label>${T('js.assigned_channels_label','Canales asignados')}<input id="maChannels" placeholder="whatsapp,telegram,messenger" value="${esc(a.channels||'')}"></label><div class="grid2"><label>${T('js.welcome_msg_label','Mensaje de bienvenida')}<textarea id="maGreeting">${esc(a.greeting||'')}</textarea></label><label>${T('js.handoff_rules_label','Reglas de transferencia')}<textarea id="maHandoff">${esc(a.handoff_rules||'')}</textarea></label></div><label>${T('js.monthly_budget_label','Presupuesto mensual de respuestas')}<input id="maBudget" type="number" min="0" value="${a.monthly_budget||0}"></label><label class="check"><input id="maDefault" type="checkbox" ${a.is_default?'checked':''}> ${T('js.main_backup_agent_label','Agente principal de respaldo')}</label><div class="actions"><button type="button" id="saveAIAgent">${T('js.save','Guardar')} ${T('nav.agent','agente')}</button><button value="cancel" class="secondary">${T('js.cancel','Cancelar')}</button></div></div>`);document.addEventListener('click',async function h(e){if(e.target?.id!=='saveAIAgent')return;document.removeEventListener('click',h);const d={...a,name:$('#maName').value,type:$('#maType').value,status:$('#maStatus').value,objective:$('#maObjective').value,tone:$('#maTone').value,language:$('#maLanguage').value,instructions:$('#maInstructions').value,knowledge:$('#maKnowledge').value,tools:$('#maTools').value,channels:$('#maChannels').value,greeting:$('#maGreeting').value,handoff_rules:$('#maHandoff').value,monthly_budget:Number($('#maBudget').value||0),is_default:$('#maDefault').checked};try{await api('/api/agents',{method:a.id?'PUT':'POST',body:JSON.stringify(d)});$('#modal').close();toast(T('js.agent_saved','Agente guardado'));loadAIAgents()}catch(err){toast(err.message)} });}
window.testAIAgent=id=>{const a=aiAgents.find(x=>x.id===id);modal(`<h2>${T('js.test_agent_prefix','Probar')} ${esc(a?.name||T('js.agent_word_generic','agente'))}</h2><textarea id="maTestText" rows="5" placeholder="${T('js.real_client_message_ph','Escribe un mensaje real de cliente')}"></textarea><button type="button" id="runMATest">${T('js.test_reply_btn','Probar respuesta')}</button><div id="maTestReply" class="reply"></div><button value="cancel" class="secondary">${T('js.close','Cerrar')}</button>`);document.addEventListener('click',async function h(e){if(e.target?.id!=='runMATest')return;document.removeEventListener('click',h);$('#maTestReply').textContent=T('js.thinking','Pensando…');try{const x=await api('/api/agents/test',{method:'POST',body:JSON.stringify({agent_id:id,text:$('#maTestText').value})});$('#maTestReply').textContent=x.reply}catch(err){$('#maTestReply').textContent=err.message}})};
window.deleteAIAgent=async id=>{}; // redefinido en V13.1
async function loadAgentRoutes(){agentRoutes=await api('/api/agents/routes');$('#agentRoutesTable').innerHTML=agentRoutes.length?`<div class="admin-table-wrap"><table class="table"><tr><th>${T('js.th_priority','Prioridad')}</th><th>${T('js.th_rule','Regla')}</th><th>${T('js.th_agent','Agente')}</th><th>${T('js.th_channel','Canal')}</th><th>${T('js.th_intent_keyword','Intención / palabra')}</th><th></th></tr>${agentRoutes.map(r=>`<tr><td>${r.priority}</td><td>${esc(r.name)}</td><td>${esc(aiAgents.find(a=>a.id===r.agent_id)?.name||r.agent_id)}</td><td>${esc(r.channel)}</td><td>${esc(r.intent||'')} ${esc(r.keyword||'')}</td><td><button class="danger" onclick="deleteAgentRoute(${r.id})">${T('js.delete','Eliminar')}</button></td></tr>`).join('')}</table></div>`:`<p>${T('js.no_routing_rules','No hay reglas. El agente principal atiende como respaldo.')}</p>`}
$('#newAgentRoute').onclick=()=>{if(!aiAgents.length)return toast(T('js.create_agent_first','Crea primero un agente'));modal(`<h2>${T('js.new_routing_rule_title','Nueva regla de enrutamiento')}</h2><div class="form"><label>${T('js.name_label','Nombre')}<input id="arName"></label><label>${T('js.th_agent','Agente')}<select id="arAgent">${aiAgents.map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select></label><div class="grid2"><label>${T('js.th_priority','Prioridad')}<input id="arPriority" type="number" value="100"></label><label>${T('js.th_channel','Canal')}<select id="arChannel"><option value="*">${T('js.all_word','Todos')}</option><option>whatsapp</option><option>telegram</option><option>messenger</option><option>landing</option><option>group</option></select></label></div><div class="grid2"><label>${T('js.intent_label','Intención')}<input id="arIntent" placeholder="${T('js.intent_ph','sales, support, appointment')}"></label><label>${T('js.keyword_label2','Palabra clave')}<input id="arKeyword"></label></div><button type="button" id="saveAgentRoute">${T('js.save_rule','Guardar regla')}</button><button value="cancel" class="secondary">${T('js.cancel','Cancelar')}</button></div>`);document.addEventListener('click',async function h(e){if(e.target?.id!=='saveAgentRoute')return;document.removeEventListener('click',h);try{await api('/api/agents/routes',{method:'POST',body:JSON.stringify({name:$('#arName').value,agent_id:Number($('#arAgent').value),priority:Number($('#arPriority').value),channel:$('#arChannel').value,intent:$('#arIntent').value,keyword:$('#arKeyword').value,enabled:true})});$('#modal').close();loadAgentRoutes();toast(T('js.rule_created','Regla creada'))}catch(err){toast(err.message)}})};
window.deleteAgentRoute=async id=>{await api('/api/agents/routes?id='+id,{method:'DELETE'});loadAgentRoutes()};
async function loadAgentMetrics(){const period=$('#agentMetricPeriod').value||new Date().toISOString().slice(0,7),x=await api('/api/agents/metrics?period='+period);agentMetrics=x.metrics||[];$('#agentMetricsTable').innerHTML=`<div class="admin-table-wrap"><table class="table"><tr><th>${T('js.th_agent','Agente')}</th><th>${T('js.th_conversations','Conversaciones')}</th><th>${T('js.th_responses','Respuestas')}</th><th>${T('js.th_tokens','Tokens')}</th><th>${T('js.th_errors','Errores')}</th><th>${T('js.th_est_cost','Costo est.')}</th></tr>${agentMetrics.map(m=>`<tr><td>${esc(m.name)}</td><td>${m.conversations}</td><td>${m.responses}</td><td>${(m.input_tokens||0)+(m.output_tokens||0)}</td><td>${m.errors}</td><td>${Number(m.estimated_cost||0).toFixed(4)} USD</td></tr>`).join('')}</table></div>`}
$('#agentMetricPeriod').value=new Date().toISOString().slice(0,7);$('#agentMetricPeriod').onchange=loadAgentMetrics;
async function loadAgentPermissions(){try{agentPermissions=await api('/api/agents/permissions');$('#agentPermissionsTable').innerHTML=agentPermissions.length?`<div class="admin-table-wrap"><table class="table"><tr><th>${T('js.th_agent','Agente')}</th><th>${T('js.th_user','Usuario')}</th><th>${T('js.role_prefix','Rol')}</th><th>${T('js.th_view','Ver')}</th><th>${T('js.th_edit','Editar')}</th><th>${T('js.th_test','Probar')}</th><th>${T('js.th_pause','Pausar')}</th></tr>${agentPermissions.map(p=>`<tr><td>${esc(aiAgents.find(a=>a.id===p.agent_id)?.name||p.agent_id)}</td><td>${esc(p.name)}</td><td>${esc(p.role)}</td><td>${p.can_view?'✓':'—'}</td><td>${p.can_edit?'✓':'—'}</td><td>${p.can_test?'✓':'—'}</td><td>${p.can_pause?'✓':'—'}</td></tr>`).join('')}</table></div>`:`<p>${T('js.no_specific_perms','No hay permisos específicos. Se aplican los permisos generales por rol.')}</p>`}catch(e){$('#agentPermissionsTable').textContent=e.message}}
$('#newAgentPermission').onclick=async()=>{if(!aiAgents.length)return toast(T('js.create_agent_first','Crea primero un agente'));let users=[];try{users=await api('/api/admin/users')}catch(e){return toast(e.message)}modal(`<h2>${T('js.assign_perms_title','Asignar permisos')}</h2><div class="form"><label>${T('js.th_agent','Agente')}<select id="apAgent">${aiAgents.map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select></label><label>${T('js.th_user','Usuario')}<select id="apUser">${users.map(u=>`<option value="${u.id}">${esc(u.name)} · ${esc(u.role)}</option>`).join('')}</select></label><label class="check"><input id="apView" type="checkbox" checked> ${T('js.view_check','Ver')}</label><label class="check"><input id="apEdit" type="checkbox"> ${T('js.edit_check','Editar')}</label><label class="check"><input id="apTest" type="checkbox" checked> ${T('js.test_check','Probar')}</label><label class="check"><input id="apPause" type="checkbox"> ${T('js.pause_check','Pausar')}</label><button type="button" id="saveAgentPermission">${T('js.save','Guardar')}</button><button value="cancel" class="secondary">${T('js.cancel','Cancelar')}</button></div>`);document.addEventListener('click',async function h(e){if(e.target?.id!=='saveAgentPermission')return;document.removeEventListener('click',h);try{await api('/api/agents/permissions',{method:'POST',body:JSON.stringify({AgentID:Number($('#apAgent').value),UserID:Number($('#apUser').value),CanView:$('#apView').checked,CanEdit:$('#apEdit').checked,CanTest:$('#apTest').checked,CanPause:$('#apPause').checked})});$('#modal').close();loadAgentPermissions();toast(T('js.perms_saved','Permisos guardados'))}catch(err){toast(err.message)}})};

// V13.1 — UI profesional, CRUD consistente e invitaciones por WhatsApp
function professionalConfirm({title=T('js.confirm_action_default','Confirmar acción'),message='',confirmText=T('js.confirm_default','Confirmar'),danger=false}={}){
 return new Promise(resolve=>{modal(`<div class="modal-icon ${danger?'danger':'info'}">${danger?'!':'✓'}</div><h2>${esc(title)}</h2><p class="modal-copy">${esc(message)}</p><div class="actions modal-actions"><button type="button" id="professionalConfirmBtn" class="${danger?'danger':''}">${esc(confirmText)}</button><button value="cancel" class="secondary">${T('js.cancel','Cancelar')}</button></div>`);const d=$('#modal');const done=v=>{d.close();resolve(v)};$('#professionalConfirmBtn').onclick=()=>done(true);d.addEventListener('close',()=>resolve(false),{once:true})})
}
function formError(msg){let e=$('#modalFormError');if(!e){e=document.createElement('div');e.id='modalFormError';e.className='form-error';$('#modalContent').prepend(e)}e.textContent=msg;e.hidden=false}

let crmContactsCache=[],opportunitiesCache=[];
async function loadContacts(){crmContactsCache=await api('/api/crm/contacts');$('#contactsTable').innerHTML=crmContactsCache.length?`<div class="admin-table-wrap"><table class="table premium-table"><tr><th>${T('js.th_client','Cliente')}</th><th>${T('js.th_contact','Contacto')}</th><th>${T('js.th_channel','Canal')}</th><th>${T('js.th_stage','Etapa')}</th><th>${T('js.th_tags','Etiquetas')}</th><th>${T('js.th_actions','Acciones')}</th></tr>${crmContactsCache.map(x=>`<tr><td><b>${esc(x.name)}</b><small>${esc(x.email||T('js.no_email','Sin correo'))}</small></td><td>${esc(x.phone||'—')}</td><td><span class="soft-badge">${esc(x.channel||'manual')}</span></td><td>${stageLabel(x.stage||'Nuevo')}</td><td>${esc(x.tags||'—')}</td><td><div class="row-actions"><button class="secondary" onclick="contactFormById(${x.id})">${T('js.edit','Editar')}</button><button class="danger ghost-danger" onclick="deleteCRMContact(${x.id})">${T('js.delete','Eliminar')}</button></div></td></tr>`).join('')}</table></div>`:`<div class="empty-state"><b>${T('js.no_contacts_title','Aún no tienes contactos')}</b><p>${T('js.no_contacts_desc','Crea el primero o deja que Worktic los capture desde conversaciones, formularios y campañas.')}</p><button onclick="openContactForm({})">${T('contacts.new','Nuevo contacto')}</button></div>`}
