window.openContactForm=x=>{modal(`<div class="modal-heading"><span class="eyebrow">CRM</span><h2>${x.id?T('js.edit','Editar'):T('js.new','Nuevo')} ${T('js.new_contact_title','contacto')}</h2><p>${T('js.contact_info_desc','Conserva la información comercial organizada y disponible para el equipo.')}</p></div><div class="form"><div class="grid2"><label>${T('js.name_label','Nombre')}<input id="cfName" value="${esc(x.name||'')}" required></label><label>${T('js.phone_label','Teléfono')}<input id="cfPhone" value="${esc(x.phone||'')}" placeholder="${T('js.phone_ph','573001234567')}"></label></div><label>${T('auth.email_label','Correo')}<input id="cfEmail" type="email" value="${esc(x.email||'')}"></label><div class="grid2"><label>${T('js.th_channel','Canal')}<select id="cfChannel">${['manual','whatsapp','telegram','messenger','landing','form'].map(v=>`<option ${x.channel===v?'selected':''}>${v}</option>`).join('')}</select></label><label>${T('js.th_stage','Etapa')}<select id="cfStage">${['Nuevo','Contactado','Interesado','Calificado','Cotización','Negociación','Ganado','Perdido'].map(v=>`<option value="${v}" ${x.stage===v?'selected':''}>${stageLabel(v)}</option>`).join('')}</select></label></div><label>${T('js.th_tags','Etiquetas')}<input id="cfTags" value="${esc(x.tags||'')}" placeholder="${T('js.tags_ph','vip, medellín, estética')}"></label><label>${T('js.notes_label','Notas')}<textarea id="cfNotes" rows="4">${esc(x.notes||'')}</textarea></label><div class="actions"><button type="button" id="saveCRMContact">${T('js.save_contact','Guardar contacto')}</button><button value="cancel" class="secondary">${T('js.cancel','Cancelar')}</button></div></div>`);$('#saveCRMContact').onclick=async()=>{const d={...x,name:$('#cfName').value.trim(),phone:$('#cfPhone').value.trim(),email:$('#cfEmail').value.trim(),channel:$('#cfChannel').value,stage:$('#cfStage').value,tags:$('#cfTags').value.trim(),notes:$('#cfNotes').value.trim()};if(!d.name)return formError(T('js.write_contact_name','Escribe el nombre del contacto.'));try{await api('/api/crm/contacts',{method:x.id?'PUT':'POST',body:JSON.stringify(d)});$('#modal').close();toast(T('js.contact_saved','Contacto guardado'));loadContacts()}catch(e){formError(e.message)}}};
