$('#inviteTeamMember').onclick=()=>{modal(`<div class="modal-heading"><span class="eyebrow">EQUIPO</span><h2>${T('users.invite','Invitar por WhatsApp')}</h2><p>${T('js.invite_whatsapp_link_notice','Worktic creará un enlace seguro de un solo uso y abrirá WhatsApp con el mensaje listo.')}</p></div><div class="form"><div class="grid2"><label>${T('js.name_label','Nombre')}<input id="tiName"></label><label>${T('js.intl_whatsapp_label','WhatsApp internacional')}<input id="tiPhone" placeholder="573001234567"></label></div><div class="grid2"><label>${T('js.role_label2','Rol')}<select id="tiRole"><option value="agent">${T('js.role_agent','Asesor')}</option><option value="supervisor">${T('js.role_supervisor','Supervisor')}</option><option value="admin">${T('js.role_admin','Administrador')}</option></select></label><label>${T('js.area_label','Área')}<input id="tiArea" placeholder="${T('js.area_ph','Ventas, soporte, agenda...')}"></label></div><div class="permission-preview"><b>${T('js.access_by_role_title','Acceso según rol')}</b><p id="tiRoleHelp">${T('js.role_help_agent','Atenderá conversaciones asignadas, contactos, oportunidades y citas.')}</p></div><div class="actions"><button type="button" id="createTeamInvite">${T('js.create_open_whatsapp','Crear y abrir WhatsApp')}</button><button value="cancel" class="secondary">${T('js.cancel','Cancelar')}</button></div></div>`);$('#tiRole').onchange=e=>{$('#tiRoleHelp').textContent={agent:T('js.role_help_agent','Atenderá conversaciones asignadas, contactos, oportunidades y citas.'),supervisor:T('js.role_help_supervisor','Podrá supervisar conversaciones, asesores, oportunidades y métricas.'),admin:T('js.role_help_admin','Podrá administrar la operación, agentes y canales, sin controlar propiedad crítica.')}[e.target.value]};$('#createTeamInvite').onclick=async()=>{const d={name:$('#tiName').value.trim(),phone:$('#tiPhone').value.trim(),role:$('#tiRole').value,area:$('#tiArea').value.trim()};if(!d.name||!d.phone)return formError(T('js.complete_name_whatsapp','Completa nombre y WhatsApp internacional.'));try{const x=await api('/api/team/invitations',{method:'POST',body:JSON.stringify(d)});$('#modal').close();loadUsers();toast(T('js.invitation_created','Invitación creada'));window.open(x.whatsapp_url,'_blank','noopener')}catch(e){formError(e.message)}}};
