window.deleteAIAgent=async id=>{if(!await professionalConfirm({title:T('js.delete_ai_agent_title','Eliminar agente IA'),message:T('js.delete_ai_agent_msg','También se eliminarán sus reglas relacionadas. El agente principal no puede eliminarse.'),confirmText:T('js.delete_agent_btn','Eliminar agente'),danger:true}))return;try{await api('/api/agents?id='+id,{method:'DELETE'});toast(T('js.agent_deleted','Agente eliminado'));loadAIAgents()}catch(e){toast(e.message)}};

let automationRulesCache=[];
async function loadRules(){automationRulesCache=await api('/api/rules');$('#rulesList').innerHTML=automationRulesCache.length?automationRulesCache.map(r=>`<div class="card automation-card"><div class="top"><div><b>${esc(r.name)}</b><small>${r.enabled?T('js.active','Activa'):T('js.paused','Pausada')}</small></div><span class="soft-badge">${esc(r.match_type)}</span></div><p><b>${esc(r.keyword)}</b> → ${esc(r.response)}</p><div class="row-actions"><button class="secondary" onclick="editAutomationRule(${r.id})">${T('js.edit','Editar')}</button><button class="danger ghost-danger" onclick="delRule(${r.id})">${T('js.delete','Eliminar')}</button></div></div>`).join(''):`<div class="empty-state compact"><b>${T('js.no_automations','No hay automatizaciones')}</b><p>${T('js.no_automations_desc','Crea reglas sencillas para responder antes de invocar a la IA.')}</p></div>`}
window.editAutomationRule=id=>{const r=automationRulesCache.find(x=>x.id===id);if(!r)return;modal(`<div class="modal-heading"><span class="eyebrow">${T('js.automation_word','AUTOMATIZACIÓN')}</span><h2>${T('js.edit_rule_title','Editar regla')}</h2><p>${T('js.edit_rule_desc','Ajusta la condición y la respuesta automática.')}</p></div><div class="form"><label>${T('js.name_label','Nombre')}<input id="erName" value="${esc(r.name)}"></label><div class="grid2"><label>${T('rules.match_label','Coincidencia')}<select id="erType"><option value="contains" ${r.match_type==='contains'?'selected':''}>${T('rules.match_contains','Contiene')}</option><option value="exact" ${r.match_type==='exact'?'selected':''}>${T('js.exact_word','Exacta')}</option><option value="starts" ${r.match_type==='starts'?'selected':''}>${T('rules.match_starts','Empieza por')}</option></select></label><label>${T('rules.keyword_label','Palabra o frase')}<input id="erKeyword" value="${esc(r.keyword)}"></label></div><label>${T('rules.response_label','Respuesta')}<textarea id="erResponse" rows="5">${esc(r.response)}</textarea></label><label class="switch-row"><span><b>${T('js.rule_active_label','Regla activa')}</b><small>${T('js.rule_pause_desc','Puede pausarse sin eliminarla.')}</small></span><input id="erEnabled" type="checkbox" ${r.enabled?'checked':''}></label><div class="actions"><button type="button" id="saveEditedRule">${T('js.save_changes','Guardar cambios')}</button><button value="cancel" class="secondary">${T('js.cancel','Cancelar')}</button></div></div>`);$('#saveEditedRule').onclick=async()=>{const d={...r,name:$('#erName').value.trim(),match_type:$('#erType').value,keyword:$('#erKeyword').value.trim(),response:$('#erResponse').value.trim(),enabled:$('#erEnabled').checked};if(!d.name||!d.keyword||!d.response)return formError(T('js.complete_name_condition_reply','Completa nombre, condición y respuesta.'));try{await api('/api/rules',{method:'PUT',body:JSON.stringify(d)});$('#modal').close();toast(T('js.automation_updated','Automatización actualizada'));loadRules()}catch(e){formError(e.message)}}};
window.delRule=async id=>{if(!await professionalConfirm({title:T('js.delete_automation_title','Eliminar automatización'),message:T('js.delete_automation_msg','La regla dejará de responder inmediatamente.'),confirmText:T('js.delete','Eliminar'),danger:true}))return;await api('/api/rules?id='+id,{method:'DELETE'});toast(T('js.automation_deleted','Automatización eliminada'));loadRules()};

async function loadAppointments(){const xs=await api('/api/appointments');$('#appointmentsTable').innerHTML=xs.length?`<div class="admin-table-wrap"><table class="table premium-table"><tr><th>${T('js.th_date','Fecha')}</th><th>${T('js.th_client','Cliente')}</th><th>${T('js.th_service','Servicio')}</th><th>${T('js.th_status','Estado')}</th><th>${T('js.th_actions','Acciones')}</th></tr>${xs.map(x=>`<tr><td>${new Date(x.starts_at).toLocaleString()}</td><td><b>${esc(x.contact_name)}</b><small>${esc(x.contact_phone)}</small></td><td>${esc(x.service)}</td><td><span class="soft-badge">${esc(apptStatusLabel(x.status))}</span></td><td><div class="row-actions"><button class="secondary" onclick='appointmentForm(${JSON.stringify(x)})'>${T('js.edit','Editar')}</button><button class="danger ghost-danger" onclick="deleteAppointment(${x.id})">${T('js.delete','Eliminar')}</button></div></td></tr>`).join('')}</table></div>`:`<div class="empty-state"><b>${T('js.no_appointments','No hay citas')}</b><p>${T('js.no_appointments_desc','Registra una cita manualmente o permite que el agente IA la cree.')}</p><button onclick="appointmentForm({duration_minutes:30,status:'Programada'})">${T('appt.new','Nueva cita')}</button></div>`}
window.deleteAppointment=async id=>{if(!await professionalConfirm({title:T('js.delete_appt_title','Eliminar cita'),message:T('js.delete_appt_msg','La cita será eliminada de la agenda. Considera cancelarla si necesitas conservar el historial.'),confirmText:T('js.delete','Eliminar'),danger:true}))return;await api('/api/appointments?id='+id,{method:'DELETE'});toast(T('js.appt_deleted','Cita eliminada'));loadAppointments()};

window.reviewPayment=(id,action)=>{modal(`<div class="modal-heading"><span class="eyebrow">${T('js.payment_verification_title','VERIFICACIÓN DE PAGO')}</span><h2>${action==='approve'?T('js.approve_payment_title','Aprobar pago'):T('js.reject_payment_title','Rechazar pago')}</h2><p>${action==='approve'?T('js.approve_payment_desc','Confirma que verificaste red, token, destino, monto y confirmaciones.'):T('js.reject_payment_desc','Registra un motivo claro para el cliente.')}</p></div><div class="form"><label>${T('js.admin_note_label','Nota administrativa')}<textarea id="paymentReviewNote" rows="4" placeholder="${action==='approve'?T('js.optional_word','Opcional'):T('js.rejection_reason_ph','Motivo del rechazo')}"></textarea></label><div class="actions"><button type="button" id="confirmPaymentReview" class="${action==='reject'?'danger':''}">${action==='approve'?T('js.approve_activate_plan','Aprobar y activar plan'):T('js.reject_payment_btn','Rechazar pago')}</button><button value="cancel" class="secondary">${T('js.cancel','Cancelar')}</button></div></div>`);$('#confirmPaymentReview').onclick=async()=>{const note=$('#paymentReviewNote').value.trim();if(action==='reject'&&!note)return formError(T('js.write_rejection_reason','Escribe el motivo del rechazo.'));try{await api('/api/admin/payments',{method:'PUT',body:JSON.stringify({id,action,note})});$('#modal').close();toast(action==='approve'?T('js.plan_activated','Plan activado'):T('js.payment_rejected','Pago rechazado'));loadAdmin()}catch(e){formError(e.message)}}};


// ── SOCIAL HUB PREMIUM ──────────────────────────────────────
let socialPosts=[],socialConnections=[],socialOverview={},socialAnalytics={},socialCalendarDate=new Date();
const socialPlatformMeta={facebook:['Facebook','F'],instagram:['Instagram','◎'],linkedin:['LinkedIn','in'],telegram:['Telegram','✈'],tiktok:['TikTok','♪'],youtube:['YouTube','▶']};
function socialBadge(p){const m=socialPlatformMeta[p]||[p,'•'];return `<span class="platform-badge ${p}"><i>${m[1]}</i>${m[0]}</span>`}
async function loadSocialHub(){
 try{[socialOverview,socialPosts,socialConnections,socialAnalytics]=await Promise.all([api('/api/social/overview'),api('/api/social/posts'),api('/api/social/connections'),api('/api/social/analytics')]);renderSocialStats();renderSocialOverview();applySocialPermissions();renderSocialConnections();renderSocialPosts();renderSocialCalendar();renderSocialAnalytics();ensureSocialComposer()}catch(e){toast(e.message)}
}
function renderSocialStats(){const items=[[T('social.js.connected','Redes conectadas'),socialOverview.connections||0],[T('social.js.scheduled','Programadas'),socialOverview.scheduled||0],[T('social.js.published','Publicadas'),socialOverview.published||0],[T('social.js.failed','Con error'),socialOverview.failed||0]];$('#socialStats').innerHTML=items.map(x=>`<div class="stat"><b>${x[1]}</b><small>${x[0]}</small></div>`).join('')}
function renderSocialOverview(){const upcoming=socialPosts.filter(x=>['scheduled','queued'].includes(x.status)).slice(0,5);$('#socialUpcoming').innerHTML=upcoming.length?upcoming.map(x=>`<div class="upcoming-row">${socialBadge(x.platform)}<div><b>${esc(x.title||T('social.js.post','Publicación'))}</b><small>${x.scheduled_at?new Date(x.scheduled_at).toLocaleString():T('social.js.immediate','Publicación inmediata')}</small></div><span class="status-chip ${x.status}">${x.status}</span></div>`).join(''):'<div class="empty-premium"><b>Tu calendario está libre</b><p>Crea la primera publicación multicanal.</p><button onclick="openSocialComposer()">Crear contenido</button></div>';
 const platforms=Object.keys(socialPlatformMeta);$('#socialNetworkHealth').innerHTML=platforms.map(p=>{const c=socialConnections.find(x=>x.platform===p&&x.status==='connected');return `<div class="network-row">${socialBadge(p)}<span class="connection-dot ${c?'on':''}"></span><small>${c?esc(c.account_name):T('social.js.not_connected','Sin conectar')}</small></div>`}).join('')}
function switchSocialTab(tab){$$('[data-social-tab]').forEach(x=>x.classList.toggle('active',x.dataset.socialTab===tab));$$('.social-panel').forEach(x=>x.classList.toggle('active',x.id==='social-'+tab));if(tab==='calendar')renderSocialCalendar();if(tab==='composer')ensureSocialComposer();if(tab==='analytics')loadSocialAnalytics()}
function socialPerm(k){return !!(socialOverview.permissions||{})[k]}
function applySocialPermissions(){const manage=socialPerm('manage_connections'),create=socialPerm('create_draft');['socialConnect','socialConnect2'].forEach(id=>{const e=$('#'+id);if(e)e.hidden=!manage});const n=$('#socialNewPost');if(n)n.hidden=!create;const c=$('[data-social-tab="composer"]');if(c)c.hidden=!create}
window.switchSocialTab=switchSocialTab;$$('[data-social-tab]').forEach(b=>b.onclick=()=>switchSocialTab(b.dataset.socialTab));
function ensureSocialComposer(){if($('#socialComposerMount').dataset.ready)return;$('#socialComposerMount').dataset.ready='1';$('#socialComposerMount').innerHTML=`<div class="composer-premium"><div class="composer-editor"><div class="composer-head"><div><span class="eyebrow">COMPOSITOR MULTICANAL</span><h2>Transforma una idea en contenido para cada red</h2></div><span class="ai-pill">✦ IA asistida</span></div><div class="form social-form"><label>Nombre interno<input id="spName" placeholder="Ej. Lanzamiento Worktic AI"></label><label>Idea o contenido principal<textarea id="spMaster" rows="7" placeholder="Describe el mensaje, producto, promoción o historia que quieres comunicar..."></textarea></label><div class="grid2"><label>Objetivo<select id="spObjective"><option>Generar leads</option><option>Reconocimiento de marca</option><option>Tráfico a landing</option><option>Conversaciones por WhatsApp</option><option>Ventas</option></select></label><label>Formato<select id="spFormat"><option value="post">Publicación</option><option value="carousel">Carrusel</option><option value="reel">Reel / video corto</option><option value="story">Historia</option><option value="video">Video</option></select></label></div><div><b class="field-title">Selecciona las redes</b><div class="platform-selector">${Object.keys(socialPlatformMeta).map(p=>`<label class="platform-option"><input type="checkbox" value="${p}"><span>${socialBadge(p)}</span></label>`).join('')}</div></div><div class="grid2"><label>Llamado a la acción<input id="spCTA" placeholder="Ej. Empieza gratis hoy"></label><label>Enlace de destino<input id="spLink" placeholder="https://..."></label></div><label>Imagen o video (URL)<input id="spMedia" placeholder="https://..."></label><div class="grid2"><label>Fecha y hora<input id="spSchedule" type="datetime-local"></label><label>Acción<select id="spAction"><option value="draft">Guardar borrador</option><option value="schedule">Programar</option><option value="publish">Publicar ahora</option></select></label></div><div class="composer-actions"><button id="spGenerate" type="button" class="secondary">✦ Adaptar con IA</button><button id="spSave" type="button">Crear publicación multicanal</button></div></div></div><aside class="composer-preview"><div class="preview-top"><b>Vista previa</b><span id="previewPlatform">Selecciona una red</span></div><div id="socialPreview" class="phone-preview"><div class="preview-empty">Selecciona una red y escribe tu contenido para ver la adaptación.</div></div></aside></div>`;
 $$('.platform-option input').forEach(x=>x.onchange=renderSocialPreview);['spMaster','spCTA','spLink'].forEach(id=>$('#'+id).oninput=renderSocialPreview);$('#spGenerate').onclick=()=>{renderSocialPreview(true);toast(T('social.js.adapted','Versiones adaptadas por red'))};$('#spSave').onclick=createSocialPost}
function selectedSocialPlatforms(){return $$('.platform-option input:checked').map(x=>x.value)}
function localAdapt(p,body,cta){let t=body.trim();if(p==='instagram')t+=`\n\n#WorkticAI #Ventas #Automatización #InteligenciaArtificial`;if(p==='linkedin')t=`Una mirada empresarial:\n\n${t}`;if(p==='telegram')t=`📣 ${t}`;if(p==='tiktok')t=`🎬 ${t}\n\n#ParaTi #Negocios`;if(p==='youtube')t=`▶️ ${t}`;if(cta)t+=`\n\n${cta}`;return t}
function renderSocialPreview(){const ps=selectedSocialPlatforms(),p=ps[0],body=$('#spMaster')?.value||'',cta=$('#spCTA')?.value||'';if(!p){$('#socialPreview').innerHTML='<div class="preview-empty">Selecciona una red para previsualizar.</div>';return}$('#previewPlatform').innerHTML=socialBadge(p);const text=localAdapt(p,body,cta),media=$('#spMedia')?.value||'';$('#socialPreview').innerHTML=`<div class="mock-post"><div class="mock-author"><span class="mock-avatar">W</span><div><b>Worktic AI</b><small>Ahora · ${socialPlatformMeta[p][0]}</small></div></div><p>${esc(text).replace(/\n/g,'<br>')||'Tu contenido aparecerá aquí.'}</p>${media?`<div class="mock-media"><img src="${esc(media)}" onerror="this.parentElement.innerHTML='<span>Vista previa multimedia</span>'"></div>`:`<div class="mock-media"><span>Imagen o video</span></div>`}<div class="mock-reactions"><span>♡ Me gusta</span><span>◯ Comentar</span><span>↗ Compartir</span></div></div>`}
async function createSocialPost(){const platforms=selectedSocialPlatforms();if(!$('#spMaster').value.trim())return toast(T('social.js.write_content','Escribe el contenido principal'));if(!platforms.length)return toast(T('social.js.select_network','Selecciona al menos una red'));const action=$('#spAction').value;if(action==='schedule'&&!$('#spSchedule').value)return toast(T('social.js.select_datetime','Selecciona fecha y hora'));try{await api('/api/social/posts',{method:'POST',body:JSON.stringify({name:$('#spName').value,objective:$('#spObjective').value,masterContent:$('#spMaster').value,format:$('#spFormat').value,cta:$('#spCTA').value,linkURL:$('#spLink').value,mediaURL:$('#spMedia').value,scheduledAt:$('#spSchedule').value?new Date($('#spSchedule').value).toISOString():'',action,platforms})});toast(T('social.js.created','Contenido multicanal creado'));['spName','spMaster','spCTA','spLink','spMedia','spSchedule'].forEach(id=>$('#'+id).value='');$$('.platform-option input').forEach(x=>x.checked=false);await loadSocialHub();switchSocialTab('library')}catch(e){toast(e.message)}}
window.openSocialComposer=()=>{switchSocialTab('composer');setTimeout(()=>$('#spMaster')?.focus(),100)};$('#socialNewPost').onclick=openSocialComposer;
function openSocialConnection(){if(!socialPerm('manage_connections'))return toast('Solo propietarios y administradores pueden conectar redes');modal(`<h2>Conectar red social</h2><p class="muted">Usa OAuth oficial para Meta, LinkedIn, TikTok y YouTube. Telegram se conecta mediante BotFather.</p><label>Red<select id="scPlatform">${Object.entries(socialPlatformMeta).map(([k,v])=>`<option value="${k}">${v[0]}</option>`).join('')}</select></label><label>Modo<select id="scMode"><option value="official">API oficial</option><option value="sandbox">Sandbox / pruebas</option></select></label><div id="socialOfficialFields"></div><div class="notice">Las APIs oficiales requieren registrar Worktic AI, configurar las URL de retorno y obtener aprobación de permisos cuando el proveedor la exija.</div><div class="actions"><button type="button" id="saveSocialConnection">Continuar conexión</button><button value="cancel" class="secondary">Cancelar</button></div>`);
 const renderFields=()=>{const p=$('#scPlatform').value,m=$('#scMode').value,box=$('#socialOfficialFields');if(m==='sandbox'){box.innerHTML='<label>Nombre visible<input id="scName" placeholder="Ej. Worktic AI Colombia"></label><label>ID de prueba<input id="scExternal" placeholder="Opcional"></label>';return}if(p==='telegram'){box.innerHTML='<label>Nombre del canal<input id="scName" placeholder="Ej. Canal Worktic AI"></label><label>Token de BotFather<input id="scToken" type="password" autocomplete="off" placeholder="123456:ABC..."></label><label>ID o usuario del canal<input id="scChat" placeholder="@canal o -100..."></label>';return}box.innerHTML=`<div class="oauth-provider-card">${socialBadge(p)}<div><b>Conexión segura OAuth 2.0</b><small>Serás redirigido al proveedor para autorizar la cuenta.</small></div></div>`};
 $('#scPlatform').onchange=renderFields;$('#scMode').onchange=renderFields;renderFields();
 document.addEventListener('click',async function h(e){if(e.target?.id!=='saveSocialConnection')return;document.removeEventListener('click',h);const p=$('#scPlatform').value,m=$('#scMode').value;try{if(m==='official'&&p!=='telegram'){const r=await api('/api/social/oauth/start?platform='+encodeURIComponent(p));window.location.href=r.authorization_url;return}await api('/api/social/connections',{method:'POST',body:JSON.stringify({platform:p,account_name:$('#scName')?.value||('Cuenta '+socialPlatformMeta[p][0]),external_account_id:$('#scExternal')?.value||'',provider_mode:m,token:$('#scToken')?.value||'',chat_id:$('#scChat')?.value||''})});$('#modal').close();toast(T('social.js.connection_saved','Conexión guardada'));loadSocialHub()}catch(err){toast(err.message)}})}
$('#socialConnect').onclick=openSocialConnection;$('#socialConnect2').onclick=openSocialConnection;
function renderSocialConnections(){const box=$('#socialConnectionsGrid'),manage=socialPerm('manage_connections');box.innerHTML=socialConnections.length?socialConnections.map(c=>`<article class="connection-card"><div class="connection-head">${socialBadge(c.platform)}<span class="status-chip ${c.status}">${c.status}</span></div><h3>${esc(c.account_name)}</h3><p>ID: ${esc(c.external_account_id)}</p><div class="connection-meta"><span>Modo <b>${esc(c.provider_mode)}</b></span><span>Permisos <b>${esc(c.scopes||'pendientes')}</b></span></div>${c.last_error?`<div class="notice">${esc(c.last_error)}</div>`:''}${manage?`<div class="actions"><button class="secondary" onclick="testSocialConnection(${c.id})">Probar</button><button class="danger" onclick="deleteSocialConnection(${c.id})">Eliminar</button></div>`:'<small class="muted">Conexión administrada por el propietario o administrador.</small>'}</article>`).join(''):`<div class="empty-premium wide"><b>No hay redes conectadas</b><p>${manage?'Conecta la primera cuenta social de la empresa.':'Solicita a un administrador que conecte las redes corporativas.'}</p>${manage?'<button onclick="document.querySelector(\'#socialConnect2\').click()">Conectar primera red</button>':''}</div>`}
window.testSocialConnection=async id=>{try{const r=await api('/api/social/test',{method:'POST',body:JSON.stringify({id})});toast(r.ok?T('social.js.connection_active','Conexión activa'):T('social.js.connection_attention','Conexión requiere atención'))}catch(e){toast(e.message)}};window.deleteSocialConnection=async id=>{if(!await professionalConfirm({title:'Eliminar conexión',message:'Las publicaciones existentes se conservarán, pero no podrán enviarse por esta cuenta.',confirmText:'Eliminar',danger:true}))return;await api('/api/social/connections?id='+id,{method:'DELETE'});loadSocialHub()};
function renderSocialPosts(){const status=$('#socialStatusFilter')?.value||'',xs=status?socialPosts.filter(x=>x.status===status):socialPosts,publish=socialPerm('publish'),del=socialPerm('delete_content');$('#socialPostsTable').innerHTML=xs.length?`<div class="admin-table-wrap"><table class="table"><tr><th>Red</th><th>Contenido</th><th>Programación</th><th>Estado</th><th>Acciones</th></tr>${xs.map(x=>`<tr><td>${socialBadge(x.platform)}</td><td><b>${esc(x.title||T('social.js.post','Publicación'))}</b><small>${esc((x.caption||'').slice(0,100))}${(x.caption||'').length>100?'…':''}</small></td><td>${x.scheduled_at?new Date(x.scheduled_at).toLocaleString():'—'}</td><td><span class="status-chip ${x.status}">${x.status}</span>${x.error_message?`<small class="error-text">${esc(x.error_message)}</small>`:''}</td><td><div class="table-actions">${publish&&x.status!=='published'?`<button onclick="publishSocialPost(${x.id})">Publicar</button>`:''}${del?`<button class="danger" onclick="deleteSocialPost(${x.id})">Eliminar</button>`:''}</div></td></tr>`).join('')}</table></div>`:'<div class="empty-premium"><b>No hay publicaciones</b><p>Crea tu primera pieza multicanal.</p></div>'}
$('#socialStatusFilter').onchange=renderSocialPosts;window.publishSocialPost=async id=>{try{const r=await api('/api/social/publish',{method:'POST',body:JSON.stringify({id})});toast(r.sandbox?T('social.js.sandbox_published','Publicación simulada correctamente'):T('social.js.published_single','Publicado'));loadSocialHub()}catch(e){toast(e.message);loadSocialHub()}};window.deleteSocialPost=async id=>{if(!await professionalConfirm({title:'Eliminar publicación',message:'La publicación será eliminada del calendario y la biblioteca.',confirmText:'Eliminar',danger:true}))return;await api('/api/social/posts?id='+id,{method:'DELETE'});loadSocialHub()};
function renderSocialCalendar(){const d=socialCalendarDate,y=d.getFullYear(),m=d.getMonth();$('#socialMonthLabel').textContent=d.toLocaleDateString('es',{month:'long',year:'numeric'});const first=new Date(y,m,1),last=new Date(y,m+1,0),offset=(first.getDay()+6)%7;let cells='';['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].forEach(x=>cells+=`<div class="calendar-weekday">${x}</div>`);for(let i=0;i<offset;i++)cells+='<div class="calendar-day muted-day"></div>';for(let day=1;day<=last.getDate();day++){const dateKey=`${y}-${String(m+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`,items=socialPosts.filter(x=>(x.scheduled_at||x.created_at||'').slice(0,10)===dateKey);cells+=`<div class="calendar-day"><b>${day}</b>${items.slice(0,3).map(x=>`<div class="calendar-post ${x.platform}" title="${esc(x.title)}">${socialPlatformMeta[x.platform]?.[1]||'•'} ${esc(x.title||'Post')}</div>`).join('')}${items.length>3?`<small>+${items.length-3} más</small>`:''}</div>`}$('#socialCalendar').innerHTML=cells}
$('#socialPrevMonth').onclick=()=>{socialCalendarDate=new Date(socialCalendarDate.getFullYear(),socialCalendarDate.getMonth()-1,1);renderSocialCalendar()};$('#socialNextMonth').onclick=()=>{socialCalendarDate=new Date(socialCalendarDate.getFullYear(),socialCalendarDate.getMonth()+1,1);renderSocialCalendar()};
async function loadSocialAnalytics(){try{const f=$('#socialAnalyticsFrom')?.value,t=$('#socialAnalyticsTo')?.value,p=$('#socialAnalyticsPlatform')?.value;let q=[];if(f)q.push('from='+encodeURIComponent(f));if(t)q.push('to='+encodeURIComponent(t));if(p)q.push('platform='+encodeURIComponent(p));socialAnalytics=await api('/api/social/analytics'+(q.length?'?'+q.join('&'):''));renderSocialAnalytics()}catch(e){toast(e.message)}}
function fmtN(n){return new Intl.NumberFormat('es-ES',{notation:Number(n)>=100000?'compact':'standard',maximumFractionDigits:1}).format(Number(n)||0)}
function fmtPct(n){return (Number(n)||0).toFixed(2)+'%'}
function renderSocialAnalytics(){const a=socialAnalytics||{},k=a.kpis||{};$('#socialAnalyticsKPIs').innerHTML=[['Alcance',fmtN(k.reach)],['Impresiones',fmtN(k.impressions)],['Interacciones',fmtN(k.interactions)],['Engagement',fmtPct(k.engagement_rate)],['Clics',fmtN(k.clicks)],['CTR',fmtPct(k.ctr)],['Leads',fmtN(k.leads)],['Conversiones',fmtN(k.conversions)]].map(x=>`<div class="analytics-kpi"><small>${x[0]}</small><b>${x[1]}</b></div>`).join('');const series=a.series||[],max=Math.max(1,...series.map(x=>Number(x.reach)||0));$('#socialTrendChart').innerHTML=series.length?series.map(x=>`<div class="trend-col" title="${x.date}: ${fmtN(x.reach)} alcance"><i style="height:${Math.max(4,(Number(x.reach)||0)/max*100)}%"></i><small>${x.date.slice(5)}</small></div>`).join(''):'<div class="empty-premium"><b>Aún no hay métricas sincronizadas</b><p>Conecta una API oficial y publica contenido para comenzar.</p></div>';const f=a.funnel||{};const steps=[['Impresiones',f.impressions],['Alcance',f.reach],['Interacciones',f.interactions],['Clics',f.clicks],['Leads',f.leads],['Conversiones',f.conversions]],base=Math.max(1,Number(f.impressions)||1);$('#socialFunnel').innerHTML=steps.map((x,i)=>`<div style="width:${Math.max(34,100-i*11)}%"><span>${x[0]}</span><b>${fmtN(x[1])}</b><small>${i?fmtPct((Number(x[1])||0)/base*100):'100%'}</small></div>`).join('');const by=a.by_platform||[];$('#socialByPlatform').innerHTML=by.length?by.map(x=>`<div class="platform-analytics-row">${socialBadge(x.platform)}<div><b>${fmtN(x.reach)} alcance</b><small>${fmtN(x.interactions)} interacciones · ${fmtPct(x.engagement_rate)} engagement · ${fmtN(x.conversions)} conversiones</small></div></div>`).join(''):'<div class="empty-premium"><p>Sin datos por red en este periodo.</p></div>';const top=a.top_posts||[];$('#socialTopPosts').innerHTML=top.length?top.map((x,i)=>`<div class="top-post-row"><span>${i+1}</span>${socialBadge(x.platform)}<div><b>${esc(x.title||T('social.js.post','Publicación'))}</b><small>${fmtN(x.reach)} alcance · ${fmtN(x.interactions)} interacciones · ${fmtN(x.conversions)} conversiones</small></div></div>`).join(''):'<div class="empty-premium"><p>Aún no hay publicaciones con métricas.</p></div>'}
const _today=new Date(),_from=new Date(Date.now()-29*86400000);if($('#socialAnalyticsFrom'))$('#socialAnalyticsFrom').value=_from.toISOString().slice(0,10);if($('#socialAnalyticsTo'))$('#socialAnalyticsTo').value=_today.toISOString().slice(0,10);if($('#socialAnalyticsRefresh'))$('#socialAnalyticsRefresh').onclick=loadSocialAnalytics;


(function socialOAuthFeedback(){const q=new URLSearchParams(location.search);if(q.get('social_oauth')){setTimeout(()=>toast(q.get('social_oauth')==='success'?'Red social conectada correctamente':'No fue posible completar OAuth: '+(q.get('reason')||'')),400);history.replaceState({},'',location.pathname)}})();


window.addEventListener('worktic:langchange',()=>{if(document.querySelector('#socialhub.active')){renderSocialStats();renderSocialOverview();renderSocialConnections();renderSocialPosts();renderSocialCalendar();renderSocialAnalytics();const mount=document.querySelector('#socialComposerMount');if(mount){mount.dataset.ready='';ensureSocialComposer();}}});

/* =========================================================
   Worktic Premium Agenda + Commercial Plans
   ========================================================= */
let agendaProfessionals=[],agendaServices=[],agendaHours=[],agendaSettings={};
const agendaDays=['Dom','Lun','Mar','Mié','Jue','Vie','Sáb'];

async function loadAgendaPremium(){
  try{
    [agendaProfessionals,agendaServices,agendaHours,agendaSettings]=await Promise.all([
      api('/api/agenda/professionals'),api('/api/agenda/services'),api('/api/agenda/hours'),api('/api/agenda/settings')
    ]);
    renderAgendaProfessionals();renderAgendaServices();renderAgendaHours();fillAgendaSelectors();fillAgendaSettings();
  }catch(e){console.warn('Agenda premium:',e.message)}
}

function renderAgendaProfessionals(){
  const el=$('#agendaProfessionalsTable');if(!el)return;
  el.innerHTML=agendaProfessionals.length?`<div class="admin-table-wrap"><table class="table premium-table"><tr><th>Profesional</th><th>Contacto</th><th>Estado</th><th>Acciones</th></tr>${agendaProfessionals.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${esc(x.email||'—')}<small>${esc(x.phone||'')}</small></td><td><span class="soft-badge">${x.active?'Activo':'Inactivo'}</span></td><td><button class="secondary" onclick='agendaProfessionalForm(${JSON.stringify(x)})'>Editar</button></td></tr>`).join('')}</table></div>`:`<div class="empty-state"><b>No hay profesionales</b><p>Crea al menos uno para ofrecer disponibilidad por persona o recurso.</p><button onclick="agendaProfessionalForm({active:true})">Nuevo profesional</button></div>`;
}
function renderAgendaServices(){
  const el=$('#agendaServicesTable');if(!el)return;
  el.innerHTML=agendaServices.length?`<div class="admin-table-wrap"><table class="table premium-table"><tr><th>Servicio</th><th>Duración</th><th>Preparación</th><th>Estado</th><th></th></tr>${agendaServices.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${x.duration_minutes} min</td><td>${x.buffer_minutes} min</td><td>${x.active?'Activo':'Inactivo'}</td><td><button class="secondary" onclick='agendaServiceForm(${JSON.stringify(x)})'>Editar</button></td></tr>`).join('')}</table></div>`:`<div class="empty-state"><b>No hay servicios</b><p>Define qué puede reservar el cliente y cuánto dura.</p><button onclick="agendaServiceForm({duration_minutes:30,buffer_minutes:0,active:true})">Nuevo servicio</button></div>`;
}
function renderAgendaHours(){
  const el=$('#agendaHoursTable');if(!el)return;
  const pname=id=>id===0?'Horario general':(agendaProfessionals.find(x=>x.id===id)?.name||`ID ${id}`);
  el.innerHTML=agendaHours.length?`<div class="admin-table-wrap"><table class="table premium-table"><tr><th>Día</th><th>Profesional</th><th>Desde</th><th>Hasta</th><th>Estado</th></tr>${agendaHours.map(x=>`<tr><td><span class="day-pill">${agendaDays[x.weekday]}</span></td><td>${esc(pname(x.professional_id))}</td><td>${esc(x.start_time)}</td><td>${esc(x.end_time)}</td><td>${x.active?'Activo':'Inactivo'}</td></tr>`).join('')}</table></div>`:`<div class="empty-state"><b>No has configurado disponibilidad</b><p>Agrega bloques como lunes a viernes de 08:00 a 17:00.</p><button onclick="agendaHoursForm()">Agregar horario</button></div>`;
}
function fillAgendaSelectors(){
  const p=$('#agendaTestProfessional'),s=$('#agendaTestService');if(p)p.innerHTML=`<option value="0">Horario general</option>${agendaProfessionals.filter(x=>x.active).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}`;if(s)s.innerHTML=agendaServices.filter(x=>x.active).map(x=>`<option value="${x.id}">${esc(x.name)} · ${x.duration_minutes} min</option>`).join('');
}
function fillAgendaSettings(){if(!$('#agendaTimezone'))return;$('#agendaTimezone').value=agendaSettings.timezone||'America/Bogota';$('#agendaSlotInterval').value=String(agendaSettings.slot_interval||30);$('#agendaMinNotice').value=agendaSettings.min_notice_hours??2;$('#agendaMaxAdvance').value=agendaSettings.max_advance_days??60;$('#agendaAllowWeekends').checked=!!agendaSettings.allow_weekends}

window.agendaProfessionalForm=x=>{modal(`<div class="modal-heading"><span class="eyebrow">AGENDA</span><h2>${x.id?'Editar':'Nuevo'} profesional</h2><p>Configura la persona o recurso que recibirá citas.</p></div><div class="form"><div class="form-section"><label>Nombre<input id="agpName" value="${esc(x.name||'')}" placeholder="Ej. Laura — Ventas"></label><div class="grid2"><label>Correo<input id="agpEmail" type="email" value="${esc(x.email||'')}"></label><label>Teléfono<input id="agpPhone" value="${esc(x.phone||'')}"></label></div><label class="check"><input id="agpActive" type="checkbox" ${x.active!==false?'checked':''}> Profesional activo</label></div><div class="actions"><button type="button" id="saveAgp">Guardar profesional</button><button value="cancel" class="secondary">Cancelar</button></div></div>`);$('#saveAgp').onclick=async()=>{await api('/api/agenda/professionals',{method:x.id?'PUT':'POST',body:JSON.stringify({...x,name:$('#agpName').value,email:$('#agpEmail').value,phone:$('#agpPhone').value,active:$('#agpActive').checked})});$('#modal').close();await loadAgendaPremium();toast('Profesional guardado')}};
window.agendaServiceForm=x=>{modal(`<div class="modal-heading"><span class="eyebrow">AGENDA</span><h2>${x.id?'Editar':'Nuevo'} servicio</h2><p>La duración se utilizará para calcular los horarios disponibles.</p></div><div class="form"><div class="form-section"><label>Nombre del servicio<input id="agsName" value="${esc(x.name||'')}" placeholder="Ej. Demo personalizada"></label><div class="grid2"><label>Duración (minutos)<input id="agsDuration" type="number" min="5" value="${x.duration_minutes||30}"></label><label>Tiempo entre citas<input id="agsBuffer" type="number" min="0" value="${x.buffer_minutes||0}"></label></div><label class="check"><input id="agsActive" type="checkbox" ${x.active!==false?'checked':''}> Servicio activo</label></div><div class="actions"><button type="button" id="saveAgs">Guardar servicio</button><button value="cancel" class="secondary">Cancelar</button></div></div>`);$('#saveAgs').onclick=async()=>{await api('/api/agenda/services',{method:x.id?'PUT':'POST',body:JSON.stringify({...x,name:$('#agsName').value,duration_minutes:Number($('#agsDuration').value),buffer_minutes:Number($('#agsBuffer').value),active:$('#agsActive').checked})});$('#modal').close();await loadAgendaPremium();toast('Servicio guardado')}};
window.agendaHoursForm=()=>{modal(`<div class="modal-heading"><span class="eyebrow">DISPONIBILIDAD</span><h2>Agregar horario semanal</h2><p>El horario general aplica cuando no existe uno específico para el profesional.</p></div><div class="form"><div class="form-section"><label>Profesional<select id="aghProfessional"><option value="0">Horario general</option>${agendaProfessionals.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label><div class="grid2"><label>Día<select id="aghDay">${agendaDays.map((x,i)=>`<option value="${i}">${x}</option>`).join('')}</select></label><label>Estado<select id="aghActive"><option value="1">Activo</option><option value="0">Inactivo</option></select></label></div><div class="grid2"><label>Desde<input id="aghStart" type="time" value="08:00"></label><label>Hasta<input id="aghEnd" type="time" value="17:00"></label></div></div><div class="actions"><button type="button" id="saveAgh">Agregar horario</button><button value="cancel" class="secondary">Cancelar</button></div></div>`);$('#saveAgh').onclick=async()=>{await api('/api/agenda/hours',{method:'POST',body:JSON.stringify({professional_id:Number($('#aghProfessional').value),weekday:Number($('#aghDay').value),start_time:$('#aghStart').value,end_time:$('#aghEnd').value,active:$('#aghActive').value==='1'})});$('#modal').close();await loadAgendaPremium();toast('Horario agregado')}};

// Professional appointment editor with real availability.
window.appointmentForm=async x=>{
  if(!agendaProfessionals.length&&!agendaServices.length)await loadAgendaPremium();
  modal(`<div class="modal-heading"><span class="eyebrow">AGENDA</span><h2>${x.id?'Editar cita':'Nueva cita'}</h2><p>Selecciona servicio, profesional y un horario disponible.</p></div><div class="form"><div class="form-section"><h3 class="form-section-title">Cliente</h3><div class="grid2"><label>Nombre<input id="aName" value="${esc(x.contact_name||'')}" placeholder="Nombre completo"></label><label>Teléfono<input id="aPhone" value="${esc(x.contact_phone||'')}" placeholder="+57..."></label></div></div><div class="form-section"><h3 class="form-section-title">Reserva</h3><div class="grid2"><label>Servicio<select id="aServiceId">${agendaServices.filter(s=>s.active).map(s=>`<option value="${s.id}" data-duration="${s.duration_minutes}" ${x.service_id===s.id?'selected':''}>${esc(s.name)} · ${s.duration_minutes} min</option>`).join('')}</select></label><label>Profesional<select id="aProfessionalId"><option value="0">Horario general</option>${agendaProfessionals.filter(p=>p.active).map(p=>`<option value="${p.id}" ${x.professional_id===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label></div><div class="grid2"><label>Fecha<input id="aDate" type="date" value="${x.starts_at?x.starts_at.slice(0,10):''}"></label><label>Hora disponible<select id="aSlot"><option value="">Selecciona fecha</option></select></label></div><div class="grid2"><label>Estado<select id="aStatus">${['Programada','Confirmada','Completada','Cancelada','No asistió'].map(s=>`<option ${x.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Duración<input id="aDuration" type="number" value="${x.duration_minutes||30}" readonly></label></div></div><div class="form-section"><label>Notas<textarea id="aNotes" placeholder="Información interna para el equipo">${esc(x.notes||'')}</textarea></label></div><div class="actions"><button type="button" id="saveAppointment">Guardar cita</button><button value="cancel" class="secondary">Cancelar</button></div></div>`);
  const refresh=async()=>{const date=$('#aDate').value,sid=$('#aServiceId').value,pid=$('#aProfessionalId').value;if(!date||!sid)return;const z=await api(`/api/agenda/availability?date=${encodeURIComponent(date)}&service_id=${sid}&professional_id=${pid}`);$('#aSlot').innerHTML=z.slots.length?z.slots.map(v=>`<option value="${v}">${v.slice(11,16)}</option>`).join(''):'<option value="">Sin disponibilidad</option>';const srv=agendaServices.find(v=>v.id===Number(sid));if(srv)$('#aDuration').value=srv.duration_minutes};$('#aDate').onchange=refresh;$('#aServiceId').onchange=refresh;$('#aProfessionalId').onchange=refresh;if($('#aDate').value)refresh();
  $('#saveAppointment').onclick=async()=>{const srv=agendaServices.find(v=>v.id===Number($('#aServiceId').value));const raw=$('#aSlot').value;if(!raw)return formError('Selecciona una hora disponible');const d={...x,contact_name:$('#aName').value,contact_phone:$('#aPhone').value,service:srv?.name||'Servicio',service_id:Number($('#aServiceId').value),professional_id:Number($('#aProfessionalId').value),starts_at:new Date(raw).toISOString(),duration_minutes:Number($('#aDuration').value),status:$('#aStatus').value,notes:$('#aNotes').value,timezone:agendaSettings.timezone||'America/Bogota'};await api('/api/appointments',{method:x.id?'PUT':'POST',body:JSON.stringify(d)});$('#modal').close();loadAppointments();toast('Cita guardada')};
};

function bindAgendaPremium(){
  $$('.agenda-tabs button').forEach(b=>b.onclick=()=>{$$('.agenda-tabs button,.agenda-panel').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#agenda-tab-'+b.dataset.agendaTab).classList.add('active')});
  if($('#newAgendaProfessional'))$('#newAgendaProfessional').onclick=()=>agendaProfessionalForm({active:true});
  if($('#newAgendaService'))$('#newAgendaService').onclick=()=>agendaServiceForm({duration_minutes:30,buffer_minutes:0,active:true});
  if($('#newAgendaHours'))$('#newAgendaHours').onclick=agendaHoursForm;
  if($('#saveAgendaSettings'))$('#saveAgendaSettings').onclick=async()=>{await api('/api/agenda/settings',{method:'PUT',body:JSON.stringify({timezone:$('#agendaTimezone').value,slot_interval:Number($('#agendaSlotInterval').value),min_notice_hours:Number($('#agendaMinNotice').value),max_advance_days:Number($('#agendaMaxAdvance').value),allow_weekends:$('#agendaAllowWeekends').checked})});toast('Configuración de agenda guardada');await loadAgendaPremium()};
  if($('#checkAgendaAvailability'))$('#checkAgendaAvailability').onclick=async()=>{const date=$('#agendaTestDate').value;if(!date)return toast('Selecciona una fecha');const z=await api(`/api/agenda/availability?date=${date}&professional_id=${$('#agendaTestProfessional').value}&service_id=${$('#agendaTestService').value}`);$('#agendaSlots').innerHTML=z.slots.length?z.slots.map(v=>`<span class="slot-chip">${v.slice(11,16)}</span>`).join(''):'<div class="notice">No hay horas disponibles para esta combinación.</div>'};
}
setTimeout(bindAgendaPremium,0);
const __oldLoadAppointments=loadAppointments;loadAppointments=async function(){await Promise.all([__oldLoadAppointments(),loadAgendaPremium()])};

let commercialPlans=[];
async function loadCommercialPlans(){const el=$('#adminPlans');if(!el)return;commercialPlans=await api('/api/admin/plans');el.innerHTML=`<div class="admin-table-wrap"><table class="table premium-table"><tr><th>Plan</th><th>Precio</th><th>Canales</th><th>WhatsApp</th><th>Usuarios</th><th>Agentes</th><th>Estado</th><th></th></tr>${commercialPlans.map(p=>`<tr><td><b>${esc(p.name)}</b><small class="plan-feature-code">${esc(p.code)}</small></td><td>${p.price_usdt} USDT</td><td>${p.max_channels}</td><td>${p.max_whatsapp}</td><td>${p.max_users}</td><td>${p.max_agents}</td><td>${p.active?'Activo':'Inactivo'}</td><td><button class="secondary" onclick='commercialPlanForm(${JSON.stringify(p)})'>Editar</button></td></tr>`).join('')}</table></div>`}
window.commercialPlanForm=p=>{modal(`<div class="modal-heading"><span class="eyebrow">SUPERADMIN</span><h2>${p.id?'Editar':'Nuevo'} plan comercial</h2><p>Los límites se aplican en backend a todas las empresas suscritas.</p></div><div class="form"><div class="form-section"><div class="grid2"><label>Nombre<input id="plName" value="${esc(p.name||'')}"></label><label>Código<input id="plCode" value="${esc(p.code||'')}"></label></div><label>Descripción<textarea id="plDesc">${esc(p.description||'')}</textarea></label><div class="grid2"><label>Precio USDT<input id="plPrice" type="number" step="0.01" value="${p.price_usdt||0}"></label><label>Días de vigencia<input id="plDays" type="number" value="${p.billing_days||30}"></label></div></div><div class="form-section"><h3 class="form-section-title">Capacidades</h3><div class="grid2"><label>Usuarios<input id="plUsers" type="number" value="${p.max_users||1}"></label><label>Canales totales<input id="plChannels" type="number" value="${p.max_channels||1}"></label><label>WhatsApp<input id="plWA" type="number" value="${p.max_whatsapp||1}"></label><label>Telegram<input id="plTG" type="number" value="${p.max_telegram||1}"></label><label>Messenger<input id="plMSG" type="number" value="${p.max_messenger||0}"></label><label>Agentes IA<input id="plAgents" type="number" value="${p.max_agents||1}"></label><label>Contactos<input id="plContacts" type="number" value="${p.max_contacts||100}"></label><label>Respuestas IA/mes<input id="plAI" type="number" value="${p.max_ai_responses||50}"></label><label>Productos<input id="plProducts" type="number" value="${p.max_products||5}"></label><label>Automatizaciones<input id="plRules" type="number" value="${p.max_rules||1}"></label></div><label>Características JSON<textarea id="plFeatures" rows="5">${esc(p.features_json||'{}')}</textarea><small>Ejemplo: {"social_hub":true,"analytics":true,"copilot":true}</small></label><label class="check"><input id="plActive" type="checkbox" ${p.active!==false?'checked':''}> Plan activo y visible</label></div><div class="actions"><button id="saveCommercialPlan" type="button">Guardar plan</button><button value="cancel" class="secondary">Cancelar</button></div></div>`);$('#saveCommercialPlan').onclick=async()=>{const d={...p,name:$('#plName').value,code:$('#plCode').value,description:$('#plDesc').value,price_usdt:Number($('#plPrice').value),billing_days:Number($('#plDays').value),max_users:Number($('#plUsers').value),max_channels:Number($('#plChannels').value),max_whatsapp:Number($('#plWA').value),max_telegram:Number($('#plTG').value),max_messenger:Number($('#plMSG').value),max_agents:Number($('#plAgents').value),max_contacts:Number($('#plContacts').value),max_ai_responses:Number($('#plAI').value),max_products:Number($('#plProducts').value),max_rules:Number($('#plRules').value),features_json:$('#plFeatures').value,active:$('#plActive').checked};JSON.parse(d.features_json);await api('/api/admin/plans',{method:p.id?'PUT':'POST',body:JSON.stringify(d)});$('#modal').close();loadCommercialPlans();toast('Plan guardado')}};
if($('#newCommercialPlan'))$('#newCommercialPlan').onclick=()=>commercialPlanForm({billing_days:30,max_users:1,max_channels:1,max_whatsapp:1,max_telegram:1,max_messenger:0,max_agents:1,max_contacts:100,max_ai_responses:100,max_products:10,max_rules:5,features_json:'{"crm":true,"agenda":true}',active:true});
const __oldLoadAdmin=loadAdmin;loadAdmin=async function(){await Promise.all([__oldLoadAdmin(),loadCommercialPlans()])};

/* =========================================================
   Agenda CRUD Fix — edición completa y flujo dinámico
   ========================================================= */
(function agendaCrudFix(){
  const showAgendaError=e=>{console.error('Agenda:',e);if(typeof formError==='function'&&$('#modal')?.open)formError(e.message||'No fue posible guardar');else toast(e.message||'No fue posible completar la operación')};
  const confirmDelete=async(title,message)=>typeof professionalConfirm==='function'?professionalConfirm({title,message,confirmText:'Eliminar',danger:true}):confirm(message);
  const localDateTime=v=>{if(!v)return '';const s=String(v);return s.length>=16?s.slice(0,16):s};
  const displayDateTime=v=>{if(!v)return '—';const s=String(v);const d=new Date(s.length===16?s+':00':s);return Number.isNaN(d.getTime())?s.replace('T',' '):d.toLocaleString()};

  renderAgendaProfessionals=function(){
    const el=$('#agendaProfessionalsTable');if(!el)return;
    el.innerHTML=agendaProfessionals.length?`<div class="admin-table-wrap"><table class="table premium-table"><tr><th>Profesional</th><th>Contacto</th><th>Estado</th><th>Acciones</th></tr>${agendaProfessionals.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${esc(x.email||'—')}<small>${esc(x.phone||'')}</small></td><td><span class="soft-badge">${x.active?'Activo':'Inactivo'}</span></td><td><div class="row-actions"><button class="secondary agp-edit" data-id="${x.id}">Editar</button><button class="danger ghost-danger agp-delete" data-id="${x.id}">Eliminar</button></div></td></tr>`).join('')}</table></div>`:`<div class="empty-state"><b>No hay profesionales</b><p>Crea al menos uno para ofrecer disponibilidad por persona o recurso.</p><button id="agendaEmptyNewProfessional">Nuevo profesional</button></div>`;
    el.querySelectorAll('.agp-edit').forEach(b=>b.onclick=()=>agendaProfessionalForm(agendaProfessionals.find(x=>x.id===Number(b.dataset.id))||{}));
    el.querySelectorAll('.agp-delete').forEach(b=>b.onclick=()=>deleteAgendaProfessional(Number(b.dataset.id)));
    const n=el.querySelector('#agendaEmptyNewProfessional');if(n)n.onclick=()=>agendaProfessionalForm({active:true});
  };

  renderAgendaServices=function(){
    const el=$('#agendaServicesTable');if(!el)return;
    el.innerHTML=agendaServices.length?`<div class="admin-table-wrap"><table class="table premium-table"><tr><th>Servicio</th><th>Duración</th><th>Preparación</th><th>Estado</th><th>Acciones</th></tr>${agendaServices.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${x.duration_minutes} min</td><td>${x.buffer_minutes} min</td><td><span class="soft-badge">${x.active?'Activo':'Inactivo'}</span></td><td><div class="row-actions"><button class="secondary ags-edit" data-id="${x.id}">Editar</button><button class="danger ghost-danger ags-delete" data-id="${x.id}">Eliminar</button></div></td></tr>`).join('')}</table></div>`:`<div class="empty-state"><b>No hay servicios</b><p>Define qué puede reservar el cliente y cuánto dura.</p><button id="agendaEmptyNewService">Nuevo servicio</button></div>`;
    el.querySelectorAll('.ags-edit').forEach(b=>b.onclick=()=>agendaServiceForm(agendaServices.find(x=>x.id===Number(b.dataset.id))||{}));
    el.querySelectorAll('.ags-delete').forEach(b=>b.onclick=()=>deleteAgendaService(Number(b.dataset.id)));
    const n=el.querySelector('#agendaEmptyNewService');if(n)n.onclick=()=>agendaServiceForm({duration_minutes:30,buffer_minutes:0,active:true});
  };

  renderAgendaHours=function(){
    const el=$('#agendaHoursTable');if(!el)return;
    const pname=id=>id===0?'Horario general':(agendaProfessionals.find(x=>x.id===id)?.name||`ID ${id}`);
    el.innerHTML=agendaHours.length?`<div class="admin-table-wrap"><table class="table premium-table"><tr><th>Día</th><th>Profesional</th><th>Desde</th><th>Hasta</th><th>Estado</th><th>Acciones</th></tr>${agendaHours.map(x=>`<tr><td><span class="day-pill">${agendaDays[x.weekday]}</span></td><td>${esc(pname(x.professional_id))}</td><td>${esc(x.start_time)}</td><td>${esc(x.end_time)}</td><td><span class="soft-badge">${x.active?'Activo':'Inactivo'}</span></td><td><div class="row-actions"><button class="secondary agh-edit" data-id="${x.id}">Editar</button><button class="danger ghost-danger agh-delete" data-id="${x.id}">Eliminar</button></div></td></tr>`).join('')}</table></div>`:`<div class="empty-state"><b>No has configurado disponibilidad</b><p>Agrega bloques como lunes a viernes de 08:00 a 17:00.</p><button id="agendaEmptyNewHours">Agregar horario</button></div>`;
    el.querySelectorAll('.agh-edit').forEach(b=>b.onclick=()=>agendaHoursForm(agendaHours.find(x=>x.id===Number(b.dataset.id))||{}));
    el.querySelectorAll('.agh-delete').forEach(b=>b.onclick=()=>deleteAgendaHours(Number(b.dataset.id)));
    const n=el.querySelector('#agendaEmptyNewHours');if(n)n.onclick=()=>agendaHoursForm({weekday:1,start_time:'08:00',end_time:'17:00',active:true});
  };

  window.agendaProfessionalForm=x=>{
    x=x||{};
    modal(`<div class="modal-heading"><span class="eyebrow">AGENDA</span><h2>${x.id?'Editar':'Nuevo'} profesional</h2><p>Configura la persona o recurso que recibirá citas.</p></div><div class="form"><div class="form-section"><label>Nombre<input id="agpName" value="${esc(x.name||'')}" placeholder="Ej. Laura — Ventas"></label><div class="grid2"><label>Correo<input id="agpEmail" type="email" value="${esc(x.email||'')}"></label><label>Teléfono<input id="agpPhone" value="${esc(x.phone||'')}"></label></div><label class="check"><input id="agpActive" type="checkbox" ${x.active!==false?'checked':''}> Profesional activo</label></div><div class="actions"><button type="button" id="saveAgp">Guardar profesional</button><button value="cancel" class="secondary">Cancelar</button></div></div>`);
    $('#saveAgp').onclick=async()=>{try{const name=$('#agpName').value.trim();if(!name)return formError('Escribe el nombre del profesional');await api('/api/agenda/professionals',{method:x.id?'PUT':'POST',body:JSON.stringify({id:x.id||0,name,email:$('#agpEmail').value.trim(),phone:$('#agpPhone').value.trim(),active:$('#agpActive').checked})});$('#modal').close();await loadAgendaPremium();toast('Profesional guardado')}catch(e){showAgendaError(e)}};
  };

  window.agendaServiceForm=x=>{
    x=x||{};
    modal(`<div class="modal-heading"><span class="eyebrow">AGENDA</span><h2>${x.id?'Editar':'Nuevo'} servicio</h2><p>La duración y preparación se usan para calcular disponibilidad real.</p></div><div class="form"><div class="form-section"><label>Nombre del servicio<input id="agsName" value="${esc(x.name||'')}" placeholder="Ej. Demo personalizada"></label><div class="grid2"><label>Duración (minutos)<input id="agsDuration" type="number" min="5" value="${x.duration_minutes||30}"></label><label>Tiempo entre citas<input id="agsBuffer" type="number" min="0" value="${x.buffer_minutes||0}"></label></div><label class="check"><input id="agsActive" type="checkbox" ${x.active!==false?'checked':''}> Servicio activo</label></div><div class="actions"><button type="button" id="saveAgs">Guardar servicio</button><button value="cancel" class="secondary">Cancelar</button></div></div>`);
    $('#saveAgs').onclick=async()=>{try{const name=$('#agsName').value.trim(),duration=Number($('#agsDuration').value),buffer=Number($('#agsBuffer').value);if(!name)return formError('Escribe el nombre del servicio');if(duration<5)return formError('La duración mínima es de 5 minutos');if(buffer<0)return formError('El tiempo entre citas no puede ser negativo');await api('/api/agenda/services',{method:x.id?'PUT':'POST',body:JSON.stringify({id:x.id||0,name,duration_minutes:duration,buffer_minutes:buffer,active:$('#agsActive').checked})});$('#modal').close();await loadAgendaPremium();toast('Servicio guardado')}catch(e){showAgendaError(e)}};
  };

  window.agendaHoursForm=x=>{
    x=x||{weekday:1,start_time:'08:00',end_time:'17:00',active:true};
    modal(`<div class="modal-heading"><span class="eyebrow">DISPONIBILIDAD</span><h2>${x.id?'Editar':'Agregar'} horario semanal</h2><p>Los horarios específicos reemplazan al horario general para ese profesional y día.</p></div><div class="form"><div class="form-section"><label>Profesional<select id="aghProfessional"><option value="0">Horario general</option>${agendaProfessionals.map(p=>`<option value="${p.id}" ${Number(x.professional_id)===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><div class="grid2"><label>Día<select id="aghDay">${agendaDays.map((d,i)=>`<option value="${i}" ${Number(x.weekday)===i?'selected':''}>${d}</option>`).join('')}</select></label><label>Estado<select id="aghActive"><option value="1" ${x.active!==false?'selected':''}>Activo</option><option value="0" ${x.active===false?'selected':''}>Inactivo</option></select></label></div><div class="grid2"><label>Desde<input id="aghStart" type="time" value="${esc(x.start_time||'08:00')}"></label><label>Hasta<input id="aghEnd" type="time" value="${esc(x.end_time||'17:00')}"></label></div></div><div class="actions"><button type="button" id="saveAgh">${x.id?'Guardar cambios':'Agregar horario'}</button><button value="cancel" class="secondary">Cancelar</button></div></div>`);
    $('#saveAgh').onclick=async()=>{try{const start=$('#aghStart').value,end=$('#aghEnd').value;if(!start||!end||start>=end)return formError('La hora final debe ser posterior a la inicial');await api('/api/agenda/hours',{method:x.id?'PUT':'POST',body:JSON.stringify({id:x.id||0,professional_id:Number($('#aghProfessional').value),weekday:Number($('#aghDay').value),start_time:start,end_time:end,active:$('#aghActive').value==='1'})});$('#modal').close();await loadAgendaPremium();toast(x.id?'Horario actualizado':'Horario agregado')}catch(e){showAgendaError(e)}};
  };

  window.deleteAgendaProfessional=async id=>{if(!await confirmDelete('Eliminar profesional','Se eliminará el profesional. Las citas históricas conservarán su identificador.'))return;try{await api('/api/agenda/professionals?id='+id,{method:'DELETE'});await loadAgendaPremium();toast('Profesional eliminado')}catch(e){showAgendaError(e)}};
  window.deleteAgendaService=async id=>{if(!await confirmDelete('Eliminar servicio','Se eliminará el servicio de las nuevas reservas.'))return;try{await api('/api/agenda/services?id='+id,{method:'DELETE'});await loadAgendaPremium();toast('Servicio eliminado')}catch(e){showAgendaError(e)}};
  window.deleteAgendaHours=async id=>{if(!await confirmDelete('Eliminar horario','Este bloque dejará de ofrecer horas disponibles.'))return;try{await api('/api/agenda/hours?id='+id,{method:'DELETE'});await loadAgendaPremium();toast('Horario eliminado')}catch(e){showAgendaError(e)}};

  window.appointmentForm=async x=>{
    x=x||{};
    try{await loadAgendaPremium()}catch(e){return showAgendaError(e)}
    if(!agendaServices.filter(s=>s.active||s.id===x.service_id).length)return toast('Primero crea un servicio activo');
    modal(`<div class="modal-heading"><span class="eyebrow">AGENDA</span><h2>${x.id?'Editar cita':'Nueva cita'}</h2><p>Selecciona servicio, profesional y una hora realmente disponible.</p></div><div class="form"><div class="form-section"><h3 class="form-section-title">Cliente</h3><div class="grid2"><label>Nombre<input id="aName" value="${esc(x.contact_name||'')}" placeholder="Nombre completo"></label><label>Teléfono<input id="aPhone" value="${esc(x.contact_phone||'')}" placeholder="+57..."></label></div></div><div class="form-section"><h3 class="form-section-title">Reserva</h3><div class="grid2"><label>Servicio<select id="aServiceId">${agendaServices.filter(s=>s.active||s.id===x.service_id).map(s=>`<option value="${s.id}" ${Number(x.service_id)===s.id?'selected':''}>${esc(s.name)} · ${s.duration_minutes} min</option>`).join('')}</select></label><label>Profesional<select id="aProfessionalId"><option value="0" ${!x.professional_id?'selected':''}>Horario general</option>${agendaProfessionals.filter(p=>p.active||p.id===x.professional_id).map(p=>`<option value="${p.id}" ${Number(x.professional_id)===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label></div><div class="grid2"><label>Fecha<input id="aDate" type="date" value="${x.starts_at?String(x.starts_at).slice(0,10):''}"></label><label>Hora disponible<select id="aSlot"><option value="">Selecciona fecha</option></select></label></div><div class="grid2"><label>Estado<select id="aStatus">${['Programada','Confirmada','Completada','Cancelada','No asistió'].map(s=>`<option value="${s}" ${x.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Duración<input id="aDuration" type="number" value="${x.duration_minutes||30}" readonly></label></div></div><div class="form-section"><label>Notas<textarea id="aNotes" placeholder="Información interna para el equipo">${esc(x.notes||'')}</textarea></label></div><div class="actions"><button type="button" id="saveAppointment">Guardar cita</button><button value="cancel" class="secondary">Cancelar</button></div></div>`);
    const refresh=async()=>{try{const date=$('#aDate').value,sid=Number($('#aServiceId').value),pid=Number($('#aProfessionalId').value);const srv=agendaServices.find(v=>v.id===sid);if(srv)$('#aDuration').value=srv.duration_minutes;if(!date||!sid)return;const q=`/api/agenda/availability?date=${encodeURIComponent(date)}&service_id=${sid}&professional_id=${pid}${x.id?'&current_appointment_id='+x.id:''}`;const z=await api(q);let slots=[...(z.slots||[])];const current=localDateTime(x.starts_at);if(x.id&&current&&current.slice(0,10)===date&&!slots.some(v=>v.slice(0,16)===current))slots.unshift(current+':00');$('#aSlot').innerHTML=slots.length?slots.map(v=>`<option value="${v}" ${current&&v.slice(0,16)===current?'selected':''}>${v.slice(11,16)}</option>`).join(''):'<option value="">Sin disponibilidad</option>'}catch(e){showAgendaError(e)}};
    $('#aDate').onchange=refresh;$('#aServiceId').onchange=refresh;$('#aProfessionalId').onchange=refresh;if($('#aDate').value)await refresh();
    $('#saveAppointment').onclick=async()=>{try{const srv=agendaServices.find(v=>v.id===Number($('#aServiceId').value)),raw=$('#aSlot').value,name=$('#aName').value.trim();if(!name)return formError('Escribe el nombre del cliente');if(!raw)return formError('Selecciona una hora disponible');const d={...x,contact_name:name,contact_phone:$('#aPhone').value.trim(),service:srv?.name||'Servicio',service_id:Number($('#aServiceId').value),professional_id:Number($('#aProfessionalId').value),starts_at:raw.length===16?raw+':00':raw,duration_minutes:Number($('#aDuration').value),status:$('#aStatus').value,notes:$('#aNotes').value,timezone:agendaSettings.timezone||'America/Bogota'};await api('/api/appointments',{method:x.id?'PUT':'POST',body:JSON.stringify(d)});$('#modal').close();await loadAppointments();toast('Cita guardada')}catch(e){showAgendaError(e)}};
  };

  loadAppointments=async function(){
    try{const [xs]=await Promise.all([api('/api/appointments'),loadAgendaPremium()]);const el=$('#appointmentsTable');if(!el)return;el.innerHTML=xs.length?`<div class="admin-table-wrap"><table class="table premium-table"><tr><th>Fecha</th><th>Cliente</th><th>Servicio</th><th>Estado</th><th>Acciones</th></tr>${xs.map(x=>`<tr><td>${displayDateTime(x.starts_at)}</td><td><b>${esc(x.contact_name)}</b><small>${esc(x.contact_phone||'')}</small></td><td>${esc(x.service)}</td><td><span class="soft-badge">${esc(apptStatusLabel(x.status))}</span></td><td><div class="row-actions"><button class="secondary apt-edit" data-id="${x.id}">Editar</button><button class="danger ghost-danger apt-delete" data-id="${x.id}">Eliminar</button></div></td></tr>`).join('')}</table></div>`:`<div class="empty-state"><b>No hay citas</b><p>Registra una cita manualmente o permite que el agente IA la cree.</p><button id="agendaEmptyNewAppointment">Nueva cita</button></div>`;el.querySelectorAll('.apt-edit').forEach(b=>b.onclick=()=>appointmentForm(xs.find(x=>x.id===Number(b.dataset.id))||{}));el.querySelectorAll('.apt-delete').forEach(b=>b.onclick=()=>deleteAppointment(Number(b.dataset.id)));const n=el.querySelector('#agendaEmptyNewAppointment');if(n)n.onclick=()=>appointmentForm({duration_minutes:30,status:'Programada'})}catch(e){showAgendaError(e)}
  };

  const bind=()=>{
    const p=$('#newAgendaProfessional');if(p)p.onclick=()=>agendaProfessionalForm({active:true});
    const s=$('#newAgendaService');if(s)s.onclick=()=>agendaServiceForm({duration_minutes:30,buffer_minutes:0,active:true});
    const h=$('#newAgendaHours');if(h)h.onclick=()=>agendaHoursForm({weekday:1,start_time:'08:00',end_time:'17:00',active:true});
    const a=$('#newAppointment');if(a)a.onclick=()=>appointmentForm({duration_minutes:30,status:'Programada'});
    const cfg=$('#saveAgendaSettings');if(cfg)cfg.onclick=async()=>{try{const timezone=$('#agendaTimezone').value.trim();if(!timezone)return formError('Escribe una zona horaria');await api('/api/agenda/settings',{method:'PUT',body:JSON.stringify({timezone,slot_interval:Number($('#agendaSlotInterval').value),min_notice_hours:Number($('#agendaMinNotice').value),max_advance_days:Number($('#agendaMaxAdvance').value),allow_weekends:$('#agendaAllowWeekends').checked})});await loadAgendaPremium();toast('Configuración de agenda guardada')}catch(e){showAgendaError(e)}};
  };
  setTimeout(bind,0);
})();
